     1→/**
     2→ * Skills Embedding Service
     3→ *
     4→ * Uses OpenAI text-embedding-3-large (3072 dims) for high-quality
     5→ * semantic similarity detection in the RealSkills endpoint.
     6→ */
     7→
     8→import { openai } from '@ai-sdk/openai';
     9→import { prisma } from '@tpmjs/db';
    10→import { embed } from 'ai';
    11→
    12→export const SKILLS_EMBEDDING_MODEL = 'text-embedding-3-large';
    13→export const SKILLS_EMBEDDING_DIMS = 3072;
    14→export const DEFAULT_SIMILARITY_THRESHOLD = 0.8;
    15→export const CACHE_HIT_THRESHOLD = 0.95;
    16→
    17→/**
    18→ * Compute embedding for a question or skill description
    19→ */
    20→export async function embedQuestion(text: string): Promise<number[]> {
    21→  const { embedding } = await embed({
    22→    model: openai.embedding(SKILLS_EMBEDDING_MODEL),
    23→    value: text,
    24→  });
    25→  return embedding;
    26→}
    27→
    28→/**
    29→ * Compute cosine similarity between two vectors
    30→ */
    31→export function cosineSimilarity(a: number[], b: number[]): number {
    32→  if (a.length !== b.length) {
    33→    throw new Error(`Vector dimension mismatch: ${a.length} vs ${b.length}`);
    34→  }
    35→
    36→  let dotProduct = 0;
    37→  let normA = 0;
    38→  let normB = 0;
    39→
    40→  for (let i = 0; i < a.length; i++) {
    41→    const aVal = a[i] ?? 0;
    42→    const bVal = b[i] ?? 0;
    43→    dotProduct += aVal * bVal;
    44→    normA += aVal * aVal;
    45→    normB += bVal * bVal;
    46→  }
    47→
    48→  const denominator = Math.sqrt(normA) * Math.sqrt(normB);
    49→  if (denominator === 0) return 0;
    50→
    51→  return dotProduct / denominator;
    52→}
    53→
    54→export interface SimilarQuestion {
    55→  id: string;
    56→  question: string;
    57→  answer: string;
    58→  similarity: number;
    59→  createdAt: Date;
    60→}
    61→
    62→/**
    63→ * Find questions similar to a given query embedding
    64→ */
    65→export async function findSimilarQuestions(
    66→  queryEmbedding: number[],
    67→  collectionId: string,
    68→  options: {
    69→    threshold?: number;
    70→    limit?: number;
    71→    excludeId?: string;
    72→  } = {}
    73→): Promise<SimilarQuestion[]> {
    74→  const { threshold = DEFAULT_SIMILARITY_THRESHOLD, limit = 5, excludeId } = options;
    75→
    76→  // Fetch all questions for this collection
    77→  const questions = await prisma.skillQuestion.findMany({
    78→    where: {
    79→      collectionId,
    80→      ...(excludeId && { id: { not: excludeId } }),
    81→    },
    82→    select: {
    83→      id: true,
    84→      question: true,
    85→      answer: true,
    86→      embedding: true,
    87→      createdAt: true,
    88→    },
    89→  });
    90→
    91→  // Calculate similarity scores
    92→  const similar: SimilarQuestion[] = [];
    93→
    94→  for (const q of questions) {
    95→    const existingEmbedding = q.embedding as number[];
    96→    if (!existingEmbedding || existingEmbedding.length === 0) continue;
    97→
    98→    const similarity = cosineSimilarity(queryEmbedding, existingEmbedding);
    99→
   100→    if (similarity >= threshold) {
   101→      similar.push({
   102→        id: q.id,
   103→        question: q.question,
   104→        answer: q.answer,
   105→        similarity,
   106→        createdAt: q.createdAt,
   107→      });
   108→    }
   109→  }
   110→
   111→  // Sort by similarity descending and limit results
   112→  return similar.sort((a, b) => b.similarity - a.similarity).slice(0, limit);
   113→}
   114→
   115→/**
   116→ * Check for a cache hit (very similar question already answered)
   117→ * Returns the cached answer if similarity > 95%
   118→ */
   119→export async function checkCacheHit(
   120→  queryEmbedding: number[],
   121→  collectionId: string
   122→): Promise<SimilarQuestion | null> {
   123→  const similar = await findSimilarQuestions(queryEmbedding, collectionId, {
   124→    threshold: CACHE_HIT_THRESHOLD,
   125→    limit: 1,
   126→  });
   127→
   128→  if (similar.length > 0 && similar[0]) {
   129→    // Increment the similar count for analytics
   130→    await prisma.skillQuestion.update({
   131→      where: { id: similar[0].id },
   132→      data: { similarCount: { increment: 1 } },
   133→    });
   134→    return similar[0];
   135→  }
   136→
   137→  return null;
   138→}
   139→
   140→/**
   141→ * Find questions that match a text query (convenience wrapper)
   142→ */
   143→export async function searchQuestions(
   144→  query: string,
   145→  collectionId: string,
   146→  options: {
   147→    threshold?: number;
   148→    limit?: number;
   149→  } = {}
   150→): Promise<SimilarQuestion[]> {
   151→  const embedding = await embedQuestion(query);
   152→  return findSimilarQuestions(embedding, collectionId, options);
   153→}
   154→
   155→export interface SimilarityResult {
   156→  isCacheHit: boolean;
   157→  cachedAnswer: string | null;
   158→  similarQuestions: SimilarQuestion[];
   159→  embedding: number[];
   160→}
   161→
   162→/**
   163→ * Full similarity check for a new question
   164→ * - Checks for cache hit (>95% similar)
   165→ * - Returns similar questions for RAG context
   166→ */
   167→export async function checkQuestionSimilarity(
   168→  question: string,
   169→  collectionId: string
   170→): Promise<SimilarityResult> {
   171→  // Generate embedding for the question
   172→  const embedding = await embedQuestion(question);
   173→
   174→  // Check for cache hit first
   175→  const cacheHit = await checkCacheHit(embedding, collectionId);
   176→  if (cacheHit) {
   177→    return {
   178→      isCacheHit: true,
   179→      cachedAnswer: cacheHit.answer,
   180→      similarQuestions: [cacheHit],
   181→      embedding,
   182→    };
   183→  }
   184→
   185→  // Find similar questions for RAG context
   186→  const similarQuestions = await findSimilarQuestions(embedding, collectionId, {
   187→    threshold: DEFAULT_SIMILARITY_THRESHOLD,
   188→    limit: 5,
   189→  });
   190→
   191→  return {
   192→    isCacheHit: false,
   193→    cachedAnswer: null,
   194→    similarQuestions,
   195→    embedding,
   196→  };
   197→}
