     1→'use client';
     2→
     3→import { Badge } from '@tpmjs/ui/Badge/Badge';
     4→import { Button } from '@tpmjs/ui/Button/Button';
     5→import { Icon } from '@tpmjs/ui/Icon/Icon';
     6→import {
     7→  Table,
     8→  TableBody,
     9→  TableCell,
    10→  TableEmpty,
    11→  TableHead,
    12→  TableHeader,
    13→  TableRow,
    14→} from '@tpmjs/ui/Table/Table';
    15→import { useRouter } from 'next/navigation';
    16→import { useCallback, useEffect, useState } from 'react';
    17→import { CollectionForm } from '~/components/collections/CollectionForm';
    18→import { DashboardLayout } from '~/components/dashboard/DashboardLayout';
    19→
    20→interface Collection {
    21→  id: string;
    22→  name: string;
    23→  description: string | null;
    24→  toolCount: number;
    25→  isPublic: boolean;
    26→  updatedAt: string;
    27→}
    28→
    29→function formatDate(dateString: string): string {
    30→  const date = new Date(dateString);
    31→  return date.toLocaleDateString('en-US', {
    32→    month: 'short',
    33→    day: 'numeric',
    34→    year: 'numeric',
    35→  });
    36→}
    37→
    38→export default function CollectionsPage(): React.ReactElement {
    39→  const router = useRouter();
    40→  const [collections, setCollections] = useState<Collection[]>([]);
    41→  const [isLoading, setIsLoading] = useState(true);
    42→  const [error, setError] = useState<string | null>(null);
    43→  const [showCreateForm, setShowCreateForm] = useState(false);
    44→  const [isCreating, setIsCreating] = useState(false);
    45→  const [deletingId, setDeletingId] = useState<string | null>(null);
    46→
    47→  const fetchCollections = useCallback(async () => {
    48→    try {
    49→      const response = await fetch('/api/collections');
    50→      const data = await response.json();
    51→
    52→      if (data.success) {
    53→        setCollections(data.data);
    54→      } else {
    55→        if (data.error?.code === 'UNAUTHORIZED') {
    56→          router.push('/sign-in');
    57→          return;
    58→        }
    59→        setError(data.error?.message || 'Failed to fetch collections');
    60→      }
    61→    } catch (err) {
    62→      console.error('Failed to fetch collections:', err);
    63→      setError('Failed to fetch collections');
    64→    } finally {
    65→      setIsLoading(false);
    66→    }
    67→  }, [router]);
    68→
    69→  useEffect(() => {
    70→    fetchCollections();
    71→  }, [fetchCollections]);
    72→
    73→  const handleCreate = async (data: { name: string; description?: string; isPublic: boolean }) => {
    74→    setIsCreating(true);
    75→
    76→    try {
    77→      const response = await fetch('/api/collections', {
    78→        method: 'POST',
    79→        headers: { 'Content-Type': 'application/json' },
    80→        body: JSON.stringify(data),
    81→      });
    82→
    83→      const result = await response.json();
    84→
    85→      if (result.success) {
    86→        setCollections((prev) => [result.data, ...prev]);
    87→        setShowCreateForm(false);
    88→      } else {
    89→        throw new Error(result.error?.message || 'Failed to create collection');
    90→      }
    91→    } catch (err) {
    92→      console.error('Failed to create collection:', err);
    93→      throw err;
    94→    } finally {
    95→      setIsCreating(false);
    96→    }
    97→  };
    98→
    99→  const handleDelete = async (id: string, e: React.MouseEvent) => {
   100→    e.stopPropagation();
   101→    if (
   102→      !confirm('Are you sure you want to delete this collection? This action cannot be undone.')
   103→    ) {
   104→      return;
   105→    }
   106→
   107→    setDeletingId(id);
   108→
   109→    try {
   110→      const response = await fetch(`/api/collections/${id}`, {
   111→        method: 'DELETE',
   112→      });
   113→
   114→      const result = await response.json();
   115→
   116→      if (result.success) {
   117→        setCollections((prev) => prev.filter((c) => c.id !== id));
   118→      } else {
   119→        throw new Error(result.error?.message || 'Failed to delete collection');
   120→      }
   121→    } catch (err) {
   122→      console.error('Failed to delete collection:', err);
   123→      alert('Failed to delete collection');
   124→    } finally {
   125→      setDeletingId(null);
   126→    }
   127→  };
   128→
   129→  if (error) {
   130→    return (
   131→      <DashboardLayout
   132→        title="Collections"
   133→        actions={
   134→          <Button onClick={() => setShowCreateForm(true)}>
   135→            <Icon icon="plus" size="sm" className="mr-2" />
   136→            New Collection
   137→          </Button>
   138→        }
   139→      >
   140→        <div className="text-center py-16">
   141→          <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
   142→          <h2 className="text-lg font-medium text-foreground mb-2">Error</h2>
   143→          <p className="text-foreground-secondary mb-4">{error}</p>
   144→          <Button onClick={fetchCollections}>Try Again</Button>
   145→        </div>
   146→      </DashboardLayout>
   147→    );
   148→  }
   149→
   150→  return (
   151→    <DashboardLayout
   152→      title="Collections"
   153→      subtitle={
   154→        collections.length > 0
   155→          ? `${collections.length} collection${collections.length !== 1 ? 's' : ''}`
   156→          : undefined
   157→      }
   158→      actions={
   159→        !showCreateForm && (
   160→          <Button onClick={() => setShowCreateForm(true)}>
   161→            <Icon icon="plus" size="sm" className="mr-2" />
   162→            New Collection
   163→          </Button>
   164→        )
   165→      }
   166→    >
   167→      {/* Create Form */}
   168→      {showCreateForm && (
   169→        <div className="bg-surface border border-border rounded-lg p-6 mb-6">
   170→          <h2 className="text-lg font-medium text-foreground mb-4">Create New Collection</h2>
   171→          <CollectionForm
   172→            onSubmit={handleCreate}
   173→            onCancel={() => setShowCreateForm(false)}
   174→            isSubmitting={isCreating}
   175→            submitLabel="Create Collection"
   176→          />
   177→        </div>
   178→      )}
   179→
   180→      {/* Collections Table */}
   181→      <div className="bg-surface border border-border rounded-lg overflow-hidden">
   182→        <Table>
   183→          <TableHeader>
   184→            <TableRow>
   185→              <TableHead className="w-[350px]">Name</TableHead>
   186→              <TableHead>Tools</TableHead>
   187→              <TableHead>Visibility</TableHead>
   188→              <TableHead>Updated</TableHead>
   189→              <TableHead className="w-[100px] text-right">Actions</TableHead>
   190→            </TableRow>
   191→          </TableHeader>
   192→          <TableBody>
   193→            {isLoading ? (
   194→              // Loading skeleton
   195→              [0, 1, 2].map((idx) => (
   196→                <TableRow key={`collection-skeleton-${idx}`}>
   197→                  <TableCell>
   198→                    <div className="flex items-center gap-3">
   199→                      <div className="w-8 h-8 rounded-lg bg-surface-secondary animate-pulse" />
   200→                      <div className="space-y-1.5">
   201→                        <div className="h-4 w-32 bg-surface-secondary rounded animate-pulse" />
   202→                        <div className="h-3 w-48 bg-surface-secondary rounded animate-pulse" />
   203→                      </div>
   204→                    </div>
   205→                  </TableCell>
   206→                  <TableCell>
   207→                    <div className="h-4 w-12 bg-surface-secondary rounded animate-pulse" />
   208→                  </TableCell>
   209→                  <TableCell>
   210→                    <div className="h-5 w-16 bg-surface-secondary rounded animate-pulse" />
   211→                  </TableCell>
   212→                  <TableCell>
   213→                    <div className="h-4 w-24 bg-surface-secondary rounded animate-pulse" />
   214→                  </TableCell>
   215→                  <TableCell>
   216→                    <div className="h-8 w-8 bg-surface-secondary rounded animate-pulse ml-auto" />
   217→                  </TableCell>
   218→                </TableRow>
   219→              ))
   220→            ) : collections.length === 0 ? (
   221→              <TableEmpty
   222→                colSpan={5}
   223→                icon={
   224→                  <div className="w-16 h-16 rounded-full bg-primary/10 flex items-center justify-center">
   225→                    <Icon icon="folder" size="lg" className="text-primary" />
   226→                  </div>
   227→                }
   228→                title="No collections yet"
   229→                description="Create a collection to organize your tools. Collections make it easy to group related tools together and share them with your agents."
   230→                action={
   231→                  <Button onClick={() => setShowCreateForm(true)}>
   232→                    <Icon icon="plus" size="sm" className="mr-2" />
   233→                    Create Your First Collection
   234→                  </Button>
   235→                }
   236→              />
   237→            ) : (
   238→              collections.map((collection) => (
   239→                <TableRow
   240→                  key={collection.id}
   241→                  interactive
   242→                  onClick={() => router.push(`/dashboard/collections/${collection.id}`)}
   243→                  className="cursor-pointer"
   244→                >
   245→                  <TableCell>
   246→                    <div className="flex items-center gap-3">
   247→                      <div className="w-8 h-8 rounded-lg bg-primary/10 flex items-center justify-center flex-shrink-0">
   248→                        <Icon icon="folder" size="sm" className="text-primary" />
   249→                      </div>
   250→                      <div className="min-w-0">
   251→                        <p className="font-medium text-foreground truncate">{collection.name}</p>
   252→                        {collection.description && (
   253→                          <p className="text-sm text-foreground-tertiary truncate max-w-[280px]">
   254→                            {collection.description}
   255→                          </p>
   256→                        )}
   257→                      </div>
   258→                    </div>
   259→                  </TableCell>
   260→                  <TableCell>
   261→                    <span className="text-foreground-secondary">{collection.toolCount}</span>
   262→                  </TableCell>
   263→                  <TableCell>
   264→                    <Badge variant={collection.isPublic ? 'default' : 'outline'} size="sm">
   265→                      {collection.isPublic ? 'Public' : 'Private'}
   266→                    </Badge>
   267→                  </TableCell>
   268→                  <TableCell>
   269→                    <span className="text-foreground-secondary text-sm">
   270→                      {formatDate(collection.updatedAt)}
   271→                    </span>
   272→                  </TableCell>
   273→                  <TableCell>
   274→                    <div className="flex items-center justify-end">
   275→                      <Button
   276→                        size="sm"
   277→                        variant="ghost"
   278→                        onClick={(e) => handleDelete(collection.id, e)}
   279→                        disabled={deletingId === collection.id}
   280→                      >
   281→                        <Icon icon="trash" size="xs" />
   282→                      </Button>
   283→                    </div>
   284→                  </TableCell>
   285→                </TableRow>
   286→              ))
   287→            )}
   288→          </TableBody>
   289→        </Table>
   290→      </div>
   291→    </DashboardLayout>
   292→  );
   293→}
