     1→'use client';
     2→
     3→import { Button } from '@tpmjs/ui/Button/Button';
     4→import { Icon, type IconName } from '@tpmjs/ui/Icon/Icon';
     5→import Link from 'next/link';
     6→import { usePathname, useRouter } from 'next/navigation';
     7→import { useEffect, useState } from 'react';
     8→import { useSession } from '@/lib/auth-client';
     9→import { AppHeader } from '../AppHeader';
    10→
    11→interface NavItem {
    12→  href: string;
    13→  label: string;
    14→  icon: IconName;
    15→  badge?: number;
    16→}
    17→
    18→interface NavSection {
    19→  title?: string;
    20→  items: NavItem[];
    21→}
    22→
    23→const navSections: NavSection[] = [
    24→  {
    25→    items: [
    26→      { href: '/dashboard', label: 'Overview', icon: 'home' },
    27→      { href: '/dashboard/agents', label: 'Agents', icon: 'terminal' },
    28→      { href: '/dashboard/collections', label: 'Collections', icon: 'folder' },
    29→    ],
    30→  },
    31→  {
    32→    title: 'Settings',
    33→    items: [
    34→      { href: '/dashboard/settings/profile', label: 'Profile', icon: 'user' },
    35→      { href: '/dashboard/settings/api-keys', label: 'AI Provider Keys', icon: 'puzzle' },
    36→      { href: '/dashboard/settings/tpmjs-api-keys', label: 'Platform API Keys', icon: 'key' },
    37→      { href: '/dashboard/settings/bridge', label: 'Bridge', icon: 'link' },
    38→      { href: '/dashboard/usage', label: 'Usage', icon: 'globe' },
    39→    ],
    40→  },
    41→];
    42→
    43→const likesNavItems: NavItem[] = [
    44→  { href: '/dashboard/likes/tools', label: 'Tools', icon: 'puzzle' },
    45→  { href: '/dashboard/likes/collections', label: 'Collections', icon: 'folder' },
    46→  { href: '/dashboard/likes/agents', label: 'Agents', icon: 'terminal' },
    47→];
    48→
    49→interface DashboardLayoutProps {
    50→  children: React.ReactNode;
    51→  /** Title displayed in the header */
    52→  title: string;
    53→  /** Optional subtitle/description */
    54→  subtitle?: string;
    55→  /** Action buttons for the header */
    56→  actions?: React.ReactNode;
    57→  /** Whether to show back button */
    58→  showBackButton?: boolean;
    59→  /** Custom back URL (defaults to parent route) */
    60→  backUrl?: string;
    61→  /** Whether to use full height layout (for chat interfaces) - removes padding and fills viewport */
    62→  fullHeight?: boolean;
    63→}
    64→
    65→export function DashboardLayout({
    66→  children,
    67→  title,
    68→  subtitle,
    69→  actions,
    70→  showBackButton,
    71→  backUrl,
    72→  fullHeight,
    73→}: DashboardLayoutProps): React.ReactElement {
    74→  const pathname = usePathname();
    75→  const router = useRouter();
    76→  const { data: session, isPending } = useSession();
    77→  const [sidebarOpen, setSidebarOpen] = useState(false);
    78→  const [likesExpanded, setLikesExpanded] = useState(() => {
    79→    if (typeof window !== 'undefined') {
    80→      const stored = localStorage.getItem('dashboard-likes-expanded');
    81→      return stored === 'true';
    82→    }
    83→    return false;
    84→  });
    85→
    86→  // Persist likes expanded state
    87→  useEffect(() => {
    88→    localStorage.setItem('dashboard-likes-expanded', String(likesExpanded));
    89→  }, [likesExpanded]);
    90→
    91→  // Auto-expand if on a likes page - intentional route-based UI sync
    92→  useEffect(() => {
    93→    if (pathname.startsWith('/dashboard/likes')) {
    94→      // eslint-disable-next-line react-hooks/set-state-in-effect
    95→      setLikesExpanded(true);
    96→    }
    97→  }, [pathname]);
    98→
    99→  // Redirect to sign-in if not authenticated
   100→  useEffect(() => {
   101→    if (!isPending && !session) {
   102→      router.push('/sign-in');
   103→    }
   104→  }, [isPending, session, router]);
   105→
   106→  // Close sidebar on route change - intentional route-based UI sync
   107→  // biome-ignore lint/correctness/useExhaustiveDependencies: pathname triggers effect
   108→  useEffect(() => {
   109→    // eslint-disable-next-line react-hooks/set-state-in-effect
   110→    setSidebarOpen(false);
   111→  }, [pathname]);
   112→
   113→  const isActive = (href: string) => {
   114→    if (href === '/dashboard') {
   115→      return pathname === '/dashboard';
   116→    }
   117→    return pathname.startsWith(href);
   118→  };
   119→
   120→  const isLikesActive = pathname.startsWith('/dashboard/likes');
   121→
   122→  const getBackUrl = () => {
   123→    if (backUrl) return backUrl;
   124→    // Get parent route
   125→    const parts = pathname.split('/').filter(Boolean);
   126→    parts.pop();
   127→    return parts.length > 0 ? `/${parts.join('/')}` : '/dashboard';
   128→  };
   129→
   130→  if (isPending) {
   131→    return (
   132→      <div className="min-h-screen bg-background">
   133→        <AppHeader />
   134→        <div className="flex items-center justify-center h-[calc(100vh-64px)]">
   135→          <div className="animate-pulse text-foreground-secondary">Loading...</div>
   136→        </div>
   137→      </div>
