     1→/**
     2→ * Page Brief Tool for TPMJS
     3→ * Fetches a URL, extracts main content using Readability, and returns a structured brief
     4→ * with summary, key points, and claims needing citations.
     5→ *
     6→ * @requires Node.js 18+ (uses native fetch API)
     7→ */
     8→
     9→import { Readability } from '@mozilla/readability';
    10→import { jsonSchema, tool } from 'ai';
    11→import { JSDOM } from 'jsdom';
    12→import sbd from 'sbd';
    13→
    14→// Verify fetch is available (Node.js 18+)
    15→if (typeof globalThis.fetch !== 'function') {
    16→  throw new Error('Page Brief tool requires Node.js 18+ with native fetch support');
    17→}
    18→
    19→/**
    20→ * Output interface for the page brief
    21→ */
    22→export interface PageBrief {
    23→  url: string;
    24→  title: string;
    25→  summary: string;
    26→  keyPoints: string[];
    27→  claimsNeedingCitation: Array<{
    28→    claim: string;
    29→    reason: string;
    30→  }>;
    31→  metadata: {
    32→    wordCount: number;
    33→    fetchedAt: string;
    34→    domain: string;
    35→  };
    36→}
    37→
    38→type PageBriefInput = {
    39→  url: string;
    40→};
    41→
    42→/**
    43→ * Validates that a string is a valid URL
    44→ */
    45→function isValidUrl(urlString: string): boolean {
    46→  try {
    47→    const url = new URL(urlString);
    48→    return url.protocol === 'http:' || url.protocol === 'https:';
    49→  } catch {
    50→    return false;
    51→  }
    52→}
    53→
    54→/**
    55→ * Extracts domain from URL
    56→ */
    57→function extractDomain(urlString: string): string {
    58→  try {
    59→    const url = new URL(urlString);
    60→    return url.hostname;
    61→  } catch {
    62→    return 'unknown';
    63→  }
    64→}
    65→
    66→/**
    67→ * Identifies claims that likely need citations based on standard research claim types.
    68→ *
    69→ * Claim categories detected (per domain entity claim.categories):
    70→ * - factual: Absolute statements with definitive language
    71→ * - statistical: Numbers, percentages, metrics
    72→ * - quote: Direct quotes or attributed statements
    73→ * - attribution: "According to", "said", "reported" patterns
    74→ * - prediction: Historical dates with event context
    75→ *
    76→ * @param sentences - Array of sentences parsed using sbd (sentence boundary detection)
    77→ * @returns Claims with reasons indicating why citation is needed
    78→ */
    79→function identifyClaimsNeedingCitation(
    80→  sentences: string[]
    81→): Array<{ claim: string; reason: string }> {
    82→  const claims: Array<{ claim: string; reason: string }> = [];
    83→
    84→  for (const sentence of sentences) {
    85→    // Skip very short sentences
    86→    if (sentence.length < 20) continue;
    87→
    88→    // Check for statistics/numbers
    89→    if (/\d+%|\d+\s*(million|billion|thousand|percent)/i.test(sentence)) {
    90→      claims.push({
    91→        claim: sentence,
    92→        reason: 'Contains statistics that should be cited',
    93→      });
    94→      continue;
    95→    }
    96→
    97→    // Check for specific years (except current/recent years in context)
    98→    if (
    99→      /\b(19|20)\d{2}\b/.test(sentence) &&
   100→      /happened|occurred|founded|established|began/i.test(sentence)
   101→    ) {
   102→      claims.push({
   103→        claim: sentence,
   104→        reason: 'Contains historical date claim',
   105→      });
   106→      continue;
   107→    }
   108→
   109→    // Check for quotes or attributions
   110→    if (
   111→      /"[^"]{10,}"/.test(sentence) ||
   112→      /according to|said|stated|claimed|reported/i.test(sentence)
   113→    ) {
   114→      claims.push({
   115→        claim: sentence,
   116→        reason: 'Contains quote or attribution that needs verification',
   117→      });
   118→      continue;
   119→    }
   120→
   121→    // Check for definitive statements about facts
   122→    if (
   123→      /\b(always|never|every|all|none|is the (first|only|largest|smallest|best|worst))\b/i.test(
   124→        sentence
   125→      )
   126→    ) {
   127→      claims.push({
   128→        claim: sentence,
   129→        reason: 'Contains absolute claim that may need verification',
   130→      });
   131→      continue;
   132→    }
   133→
   134→    // Limit to top 10 claims
   135→    if (claims.length >= 10) break;
   136→  }
   137→
   138→  return claims;
   139→}
   140→
   141→/**
   142→ * Extracts key points from sentences (first sentence of each paragraph-like section)
   143→ */
   144→function extractKeyPoints(sentences: string[], maxPoints = 5): string[] {
   145→  const keyPoints: string[] = [];
   146→  const minLength = 30;
   147→  const seenStarts = new Set<string>();
   148→
   149→  for (const sentence of sentences) {
   150→    if (sentence.length < minLength) continue;
   151→
   152→    // Get first 20 chars as dedup key
   153→    const start = sentence.substring(0, 20).toLowerCase();
   154→    if (seenStarts.has(start)) continue;
   155→    seenStarts.add(start);
   156→
   157→    // Prefer sentences that look like main points
   158→    const isKeyPoint =
   159→      /^(The|A|An|This|These|It|They|We|You|First|Second|Finally|Most|Many|Some)\b/.test(
   160→        sentence
   161→      ) && sentence.length < 300;
   162→
   163→    if (isKeyPoint) {
   164→      keyPoints.push(sentence);
   165→      if (keyPoints.length >= maxPoints) break;
   166→    }
   167→  }
   168→
   169→  // If we didn't get enough, add more sentences
   170→  if (keyPoints.length < maxPoints) {
   171→    for (const sentence of sentences) {
   172→      if (sentence.length >= minLength && sentence.length < 300) {
   173→        const start = sentence.substring(0, 20).toLowerCase();
   174→        if (!seenStarts.has(start)) {
   175→          seenStarts.add(start);
   176→          keyPoints.push(sentence);
   177→          if (keyPoints.length >= maxPoints) break;
   178→        }
   179→      }
   180→    }
   181→  }
   182→
   183→  return keyPoints;
   184→}
   185→
   186→/**
   187→ * Creates a summary from the first few meaningful sentences
   188→ */
   189→function createSummary(sentences: string[], maxSentences = 3): string {
   190→  const meaningfulSentences = sentences.filter((s) => s.length > 40 && s.length < 400);
   191→  return meaningfulSentences.slice(0, maxSentences).join(' ');
   192→}
   193→
   194→/**
   195→ * Page Brief Tool
   196→ * Fetches a URL, extracts main content, and returns a structured brief
   197→ */
   198→export const pageBriefTool = tool({
   199→  description:
   200→    'Fetch a URL, extract the main content using the Readability algorithm, and return a structured brief with summary, key points, and claims that need citations. Useful for quickly understanding what a webpage is about.',
   201→  inputSchema: jsonSchema<PageBriefInput>({
   202→    type: 'object',
   203→    properties: {
   204→      url: {
   205→        type: 'string',
   206→        description: 'The URL to fetch and analyze (must be http or https)',
   207→      },
   208→    },
   209→    required: ['url'],
   210→    additionalProperties: false,
   211→  }),
   212→  async execute({ url }): Promise<PageBrief> {
   213→    // Validate URL
   214→    if (!url || typeof url !== 'string') {
   215→      throw new Error('URL is required and must be a string');
   216→    }
   217→
   218→    if (!isValidUrl(url)) {
   219→      throw new Error(`Invalid URL: ${url}. Must be a valid http or https URL.`);
   220→    }
   221→
   222→    // Fetch the page with comprehensive error handling
   223→    let html: string;
   224→    try {
   225→      const controller = new AbortController();
   226→      const timeoutId = setTimeout(() => controller.abort(), 30000); // 30s timeout
   227→
   228→      const response = await fetch(url, {
   229→        headers: {
   230→          'User-Agent': 'Mozilla/5.0 (compatible; TPMJSBot/1.0; +https://tpmjs.com)',
   231→          Accept: 'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
   232→        },
   233→        signal: controller.signal,
   234→      });
   235→
   236→      clearTimeout(timeoutId);
   237→
   238→      if (!response.ok) {
   239→        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
   240→      }
   241→
   242→      const contentType = response.headers.get('content-type') || '';
   243→      if (!contentType.includes('text/html') && !contentType.includes('application/xhtml')) {
   244→        throw new Error(`Invalid content type: ${contentType}. Expected HTML content.`);
   245→      }
   246→
   247→      html = await response.text();
   248→
   249→      if (!html || html.trim().length === 0) {
   250→        throw new Error('Received empty response from server');
   251→      }
   252→    } catch (error) {
   253→      if (error instanceof Error) {
   254→        if (error.name === 'AbortError') {
   255→          throw new Error(`Request to ${url} timed out after 30 seconds`);
   256→        }
   257→        if (error.message.includes('ENOTFOUND') || error.message.includes('getaddrinfo')) {
   258→          throw new Error(`DNS resolution failed for ${url}. Check the domain name.`);
   259→        }
   260→        if (error.message.includes('ECONNREFUSED')) {
   261→          throw new Error(`Connection refused to ${url}. The server may be down.`);
   262→        }
   263→        if (error.message.includes('CERT_')) {
   264→          throw new Error(
   265→            `SSL certificate error for ${url}. The site may have an invalid certificate.`
   266→          );
   267→        }
   268→        throw new Error(`Failed to fetch URL ${url}: ${error.message}`);
   269→      }
   270→      throw new Error(`Failed to fetch URL ${url}: Unknown network error`);
   271→    }
   272→
   273→    // Parse with JSDOM and extract content using @mozilla/readability
   274→    // Domain rule: content_extraction - Uses @mozilla/readability for main content extraction
   275→    let article: ReturnType<Readability['parse']>;
   276→    try {
   277→      // Create DOM from HTML using jsdom
   278→      const dom = new JSDOM(html, { url });
   279→      // Use @mozilla/readability's Readability algorithm to extract main content
   280→      const reader = new Readability(dom.window.document);
   281→      article = reader.parse();
   282→    } catch (error) {
   283→      const message = error instanceof Error ? error.message : 'Unknown error';
   284→      throw new Error(`Failed to parse content from ${url}: ${message}`);
   285→    }
   286→
   287→    if (!article) {
   288→      throw new Error(
   289→        `Could not extract readable content from ${url}. The page may not have article content.`
   290→      );
   291→    }
   292→
   293→    // Extract text content and validate it's not empty
   294→    const textContent = article.textContent || '';
   295→    if (textContent.trim().length === 0) {
   296→      throw new Error(
   297→        `Extracted content from ${url} is empty. The page may be dynamically rendered or blocked.`
   298→      );
   299→    }
   300→    const sentences: string[] = sbd.sentences(textContent, {
   301→      newline_boundaries: true,
   302→      preserve_whitespace: false,
   303→    });
   304→
   305→    // Clean up sentences
   306→    const cleanSentences = sentences
   307→      .map((s: string) => s.trim())
   308→      .filter((s: string) => s.length > 10);
   309→
   310→    // Count words
   311→    const wordCount = textContent.split(/\s+/).filter((w: string) => w.length > 0).length;
   312→
   313→    // Build the brief
   314→    const brief: PageBrief = {
   315→      url,
   316→      title: article.title || 'Untitled',
   317→      summary: createSummary(cleanSentences),
   318→      keyPoints: extractKeyPoints(cleanSentences),
   319→      claimsNeedingCitation: identifyClaimsNeedingCitation(cleanSentences),
   320→      metadata: {
   321→        wordCount,
   322→        fetchedAt: new Date().toISOString(),
   323→        domain: extractDomain(url),
   324→      },
   325→    };
   326→
   327→    return brief;
   328→  },
   329→});
   330→
   331→export default pageBriefTool;
   332→

