    10→
    11→/**
    12→ * POST /api/sync/changes
    13→ * Discovery-only sync: monitors NPM changes feed, upserts packages and tools.
    14→ * Does NOT call the executor for schema extraction or health checks — that's handled by /api/sync/enrich.
    15→ *
    16→ * Called by Vercel Cron (every 4 hours) or GitHub Actions.
    17→ * Requires Authorization: Bearer <CRON_SECRET>
    18→ */
    19→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex but straightforward CRUD operation
    20→export async function POST(request: NextRequest) {
    21→  const authHeader = request.headers.get('authorization');
    22→  const token = authHeader?.replace('Bearer ', '');
    23→
    24→  if (env.CRON_SECRET && token !== env.CRON_SECRET) {
    25→    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
    26→  }
    27→
    28→  const startTime = Date.now();
