    30→  let skipped = 0;
    31→  let errors = 0;
    32→  const errorMessages: string[] = [];
    33→
    34→  try {
    35→    const checkpoint = await prisma.syncCheckpoint.findUnique({
    36→      where: { source: 'changes-feed' },
    37→    });
    38→
