// ============================================================================
// Memory Models (Persistent Semantic Memory for AI Tool Collections)
// ============================================================================

/// Memory - user-owned persistent memories for AI agents
model Memory {
  id               String    @id @default(cuid())

  // Owner relationship
  userId           String    @map("user_id")
  user             User      @relation(fields: [userId], references: [id], onDelete: Cascade)

  // Content
  content          Json      @db.JsonB // Arbitrary JSON payload
  summary          String    @db.VarChar(500) // Auto-generated or user-provided preview
  namespace        String?   @db.VarChar(100) // Grouping like "project-x", "personal"
  tags             String[]  @default([]) @db.Text // Categorization tags

  // Embedding for semantic search
  embedding        Json      @db.JsonB // 3072-dim float array (text-embedding-3-large)

  // Provenance tracking
  source           String    @db.VarChar(100) // Which tool created it ("createMemoryTool", "dashboard")
  sourceAgent      String?   @map("source_agent") @db.VarChar(200) // Agent name/identifier
  sourceContext    Json?     @map("source_context") @db.JsonB // Additional creation context

  // Size tracking
  contentSizeBytes Int       @map("content_size_bytes")

  // TTL support
  expiresAt        DateTime? @map("expires_at")

  // Timestamps
  createdAt        DateTime  @default(now()) @map("created_at")
  updatedAt        DateTime  @updatedAt @map("updated_at")

  @@index([userId])
  @@index([userId, namespace])
  @@index([userId, createdAt])
  @@index([expiresAt])
  @@map("memories")
}

