import { Icon } from '@tpmjs/ui/Icon/Icon';
import { Input } from '@tpmjs/ui/Input/Input';
import { Modal } from '@tpmjs/ui/Modal/Modal';
import {
  Table,
  TableBody,
  TableCell,
  TableEmpty,
  TableHead,
  TableHeader,
  TableRow,
} from '@tpmjs/ui/Table/Table';
import { useCallback, useEffect, useState } from 'react';
import { DashboardLayout } from '~/components/dashboard/DashboardLayout';

interface Memory {
  id: string;
  content: unknown;
  summary: string;
  namespace: string | null;
  tags: string[];
  source: string;
  sourceAgent: string | null;
  contentSizeBytes: number;
  expiresAt: string | null;
  createdAt: string;
  updatedAt: string;
  similarity?: number;
}

function formatDate(dateString: string): string {
  const date = new Date(dateString);
  return date.toLocaleDateString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  });
}

export default function MemoriesPage(): React.ReactElement {
  const [memories, setMemories] = useState<Memory[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deletingId, setDeletingId] = useState<string | null>(null);
  const [selectedMemory, setSelectedMemory] = useState<Memory | null>(null);
  const [searchQuery, setSearchQuery] = useState('');
  const [isSearching, setIsSearching] = useState(false);
  const [namespaceFilter, setNamespaceFilter] = useState<string>('');
  const [namespaces, setNamespaces] = useState<string[]>([]);

  const fetchMemories = useCallback(async () => {
    try {
      setIsLoading(true);
      const params = new URLSearchParams();
      if (namespaceFilter) params.set('namespace', namespaceFilter);

      const response = await fetch(`/api/memories?${params.toString()}`);
      const data = await response.json();

      if (data.success) {
        setMemories(data.data);
        // Extract unique namespaces for the filter
        const ns = new Set<string>();
        for (const m of data.data) {
          if (m.namespace) ns.add(m.namespace);
        }
        setNamespaces(Array.from(ns).sort());
      } else {
        setError(data.error || 'Failed to fetch memories');
      }
    } catch (err) {
      console.error('Failed to fetch memories:', err);
      setError('Failed to fetch memories');
    } finally {
      setIsLoading(false);
    }
  }, [namespaceFilter]);

  useEffect(() => {
    fetchMemories();
  }, [fetchMemories]);

  const handleSearch = async () => {
    if (!searchQuery.trim()) {
      fetchMemories();
      return;
    }

    setIsSearching(true);
    try {
      const response = await fetch('/api/memories/search', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          query: searchQuery,
          namespace: namespaceFilter || undefined,
          limit: 50,
        }),
      });
      const data = await response.json();
      if (data.success) {
        setMemories(data.data);
      } else {
        setError(data.error || 'Search failed');
      }
    } catch (err) {
      console.error('Search failed:', err);
      setError('Search failed');
    } finally {
      setIsSearching(false);
    }
  };

  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm('Are you sure you want to delete this memory?')) return;

    setDeletingId(id);
    try {
      const response = await fetch(`/api/memories/${id}`, { method: 'DELETE' });
      const result = await response.json();
      if (result.success) {
        setMemories((prev) => prev.filter((m) => m.id !== id));
        if (selectedMemory?.id === id) setSelectedMemory(null);
      } else {
        alert(result.error || 'Failed to delete memory');
      }
    } catch (err) {
      console.error('Failed to delete memory:', err);
      alert('Failed to delete memory');
    } finally {
      setDeletingId(null);
    }
  };

  if (error) {
    return (
      <DashboardLayout title="Memories">
        <div className="text-center py-16">
          <Icon icon="alertCircle" size="lg" className="mx-auto text-error mb-4" />
          <h2 className="text-lg font-medium text-foreground mb-2">Error</h2>
          <p className="text-foreground-secondary mb-4">{error}</p>
          <Button
            onClick={() => {
              setError(null);
              fetchMemories();
            }}
          >
            Try Again
          </Button>
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout
      title="Memories"
      subtitle={
        memories.length > 0
          ? `${memories.length} memor${memories.length !== 1 ? 'ies' : 'y'}`
          : undefined
      }
    >
      {/* Search and filters */}
      <div className="flex gap-3 mb-6">
        <div className="flex-1">
          <Input
            placeholder="Search memories semantically..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
          />
        </div>
        {namespaces.length > 0 && (
          <select
            value={namespaceFilter}
