  namespace?: string;
  tags?: string[];
  expiresAt?: string;
};

type SearchMemoryInput = {
  query: string;
  namespace?: string;
  tags?: string[];
  limit?: number;
  threshold?: number;
};

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------

