import { prisma } from '@tpmjs/db';
import { NextResponse } from 'next/server';
import {
  buildEmbeddingText,
  embedMemoryContent,
} from '~/lib/ai/memory-embedding';
import { API_KEY_SCOPES } from '~/lib/api-keys';
import { requireAuth } from '~/lib/api-keys/middleware';

export const runtime = 'nodejs';
export const maxDuration = 60;

const MAX_CONTENT_SIZE = 100 * 1024; // 100KB

/**
 * POST /api/memories - Create a new memory
 */
export async function POST(request: Request) {
  const { auth, errorResponse } = await requireAuth(API_KEY_SCOPES.MEMORY_WRITE);
  if (errorResponse) return errorResponse;

  let body: Record<string, unknown>;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
  }

  const { content, summary, namespace, tags, expiresAt, source, sourceAgent, sourceContext } = body as {
    content: unknown;
    summary?: string;
    namespace?: string;
    tags?: string[];
    expiresAt?: string;
    source?: string;
    sourceAgent?: string;
    sourceContext?: unknown;
  };

  if (content === undefined || content === null) {
    return NextResponse.json({ error: 'content is required' }, { status: 400 });
  }

  const contentStr = JSON.stringify(content);
  const contentSizeBytes = Buffer.byteLength(contentStr, 'utf-8');

  if (contentSizeBytes > MAX_CONTENT_SIZE) {
    return NextResponse.json(
      { error: `content exceeds maximum size of ${MAX_CONTENT_SIZE} bytes` },
      { status: 400 }
    );
  }

  // Auto-generate summary if not provided
  const memorySummary = summary || contentStr.slice(0, 500);

  // Build embedding text and generate embedding
  const embeddingText = buildEmbeddingText(
    memorySummary,
    namespace,
    tags
  );
  const embedding = await embedMemoryContent(embeddingText);

  const memory = await prisma.memory.create({
    data: {
      userId: auth!.userId!,
      content: content as object,
      summary: memorySummary,
      namespace: namespace || null,
      tags: tags || [],
      embedding,
      source: (source as string) || 'api',
      sourceAgent: sourceAgent || null,
      sourceContext: sourceContext ? (sourceContext as object) : null,
      contentSizeBytes,
      expiresAt: expiresAt ? new Date(expiresAt) : null,
    },
    select: {
      id: true,
      content: true,
      summary: true,
      namespace: true,
      tags: true,
      source: true,
      sourceAgent: true,
      sourceContext: true,
      contentSizeBytes: true,
      expiresAt: true,
      createdAt: true,
      updatedAt: true,
    },
  });

  return NextResponse.json({ success: true, data: memory }, { status: 201 });
}

/**
 * GET /api/memories - List memories
 */
export async function GET(request: Request) {
  const { auth, errorResponse } = await requireAuth(API_KEY_SCOPES.MEMORY_READ);
  if (errorResponse) return errorResponse;

  const url = new URL(request.url);
