    22→ *
    23→ * Called by Vercel Cron (every 2 minutes) or GitHub Actions.
    24→ * Requires Authorization: Bearer <CRON_SECRET>
    25→ */
    26→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Complex but straightforward queue processing
    27→export async function POST(request: NextRequest) {
    28→  const authHeader = request.headers.get('authorization');
    29→  const token = authHeader?.replace('Bearer ', '');
    30→
    31→  if (env.CRON_SECRET && token !== env.CRON_SECRET) {
    32→    return NextResponse.json({ success: false, error: 'Unauthorized' }, { status: 401 });
    33→  }
