    55→      if (Date.now() - startTime > TIME_BUDGET_MS) {
    56→        console.log('Time budget exceeded during auto-discovery phase, stopping');
    57→        break;
    58→      }
    59→
    60→      try {
    61→        console.log(`Auto-discovering tools for ${pkg.npmPackageName}...`);
    62→        const exportsResult = await listToolExports(
    63→          pkg.npmPackageName,
    64→          pkg.npmVersion,
    65→          pkg.env as Record<string, unknown> | null
    66→        );
