   100→export async function fetchPackageMetadata(packageName: string): Promise<PackageMetadata | null> {
   101→  // Encode the package name to handle scoped packages (@scope/name)
   102→  const encodedName = packageName.replace('/', '%2F');
   103→  const url = `${NPM_REGISTRY_URL}/${encodedName}`;
