   113→      return null;
   114→    }
   115→
   116→    if (!response.ok) {
   117→      throw new Error(`NPM registry error: ${response.status} ${response.statusText}`);
   118→    }
   119→
   120→    const data = await response.json();
   121→    return PackageMetadataSchema.parse(data);
