   132→ * @param packageName - The name of the package
   133→ * @returns The latest package version metadata, or null if not found
   134→ */
   135→export async function fetchLatestPackageVersion(
   136→  packageName: string
   137→): Promise<PackageVersion | null> {
   138→  const metadata = await fetchPackageMetadata(packageName);
   139→
   140→  if (!metadata) {
   141→    return null;
   142→  }
   143→
   144→  const latestTag = metadata['dist-tags'].latest;
   145→  if (!latestTag) {
   146→    return null;
   147→  }
   148→
   149→  const version = metadata.versions[latestTag as string];
   150→  if (!version) {
   151→    return null;
   152→  }
   153→
   154→  // Add publishedAt from metadata.time
   155→  const publishedAt = metadata.time?.[latestTag as string];
   156→
   157→  return {
   158→    ...version,
   159→    publishedAt,
   160→  };
   161→}
