   142→  }
   143→
   144→  const latestTag = metadata['dist-tags'].latest;
   145→  if (!latestTag) {
   146→    return null;
   147→  }
   148→
   149→  const version = metadata.versions[latestTag as string];
   150→  if (!version) {
   151→    return null;
   152→  }
   153→
   154→  // Add publishedAt from metadata.time
   155→  const publishedAt = metadata.time?.[latestTag as string];
   156→
   157→  return {
   158→    ...version,
   159→    publishedAt,
   160→  };
   161→}
   162→
   163→export type PackageVersionWithReadme = PackageVersion & {
   164→  readme?: string;
   165→  topLevelKeywords?: string[];
   166→  topLevelDescription?: string;
   167→};
   168→
   169→/**
   170→ * Gets the latest version of a package with additional top-level metadata
   171→ * @param packageName - The name of the package
   172→ * @returns The latest package version with README and top-level metadata, or null if not found
   173→ */
   174→export async function fetchLatestPackageWithMetadata(
   175→  packageName: string
   176→): Promise<PackageVersionWithReadme | null> {
   177→  const metadata = await fetchPackageMetadata(packageName);
   178→
   179→  if (!metadata) {
   180→    return null;
   181→  }
   182→
   183→  const latestTag = metadata['dist-tags'].latest;
   184→  if (!latestTag) {
   185→    return null;
   186→  }
   187→
   188→  const version = metadata.versions[latestTag as string];
   189→  if (!version) {
   190→    return null;
   191→  }
   192→
   193→  // Add publishedAt from metadata.time
   194→  const publishedAt = metadata.time?.[latestTag as string];
   195→
   196→  return {
   197→    ...version,
   198→    publishedAt,
   199→    readme: metadata.readme,
   200→    topLevelKeywords: metadata.keywords,
   201→    topLevelDescription: metadata.description,
   202→  };
   203→}
   204→
   205→/**
   206→ * Checks if a package has a tpmjs field in its latest version
   207→ * @param packageName - The name of the package
   208→ * @returns The tpmjs field if present, null otherwise
   209→ */
   210→export async function fetchPackageTpmjsField(packageName: string): Promise<unknown | null> {
   211→  const latestVersion = await fetchLatestPackageVersion(packageName);
   212→
   213→  if (!latestVersion) {
   214→    return null;
   215→  }
   216→
   217→  return latestVersion.tpmjs || null;
   218→}
