{
  "name": "@tpmjs/official-memory",
  "version": "0.1.0",
  "description": "Persistent, semantically-searchable memory tools for AI agents. Create and search memories across sessions.",
  "type": "module",
  "keywords": [
    "tpmjs",
    "memory",
    "ai",
    "semantic-search",
    "embeddings"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "type-check": "tsc --noEmit",
    "clean": "rm -rf dist .turbo"
  },
  "devDependencies": {
    "@tpmjs/tsconfig": "workspace:*",
    "tsup": "^8.5.1",
    "typescript": "^5.9.3"
  },
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/tpmjs/tpmjs.git",
    "directory": "packages/tools/official/memory"
  },
  "homepage": "https://tpmjs.com",
  "license": "MIT",
  "tpmjs": {
    "category": "memory",
    "frameworks": [
      "vercel-ai"
    ],
    "tools": [
      {
        "name": "createMemoryTool",
        "description": "Store a persistent memory that can be retrieved later via semantic search. Use for saving context, decisions, preferences, or any information that should persist across sessions.",
        "parameters": [
          {
            "name": "content",
            "type": "object",
            "description": "Arbitrary JSON payload to store as the memory content",
            "required": true
          },
          {
            "name": "summary",
            "type": "string",
            "description": "Human-readable summary of the memory (max 500 chars). Auto-generated if not provided.",
            "required": false
          },
          {
            "name": "namespace",
            "type": "string",
            "description": "Optional grouping namespace (e.g., 'project-x', 'personal')",
            "required": false
          },
          {
            "name": "tags",
            "type": "array",
            "description": "Tags for categorization",
            "required": false
          },
          {
            "name": "expiresAt",
            "type": "string",
            "description": "ISO 8601 datetime for automatic expiration (TTL)",
            "required": false
          }
        ],
        "returns": {
          "type": "Memory",
          "description": "The created memory object with id, content, summary, namespace, tags, and timestamps"
        }
      },
      {
        "name": "searchMemoryTool",
        "description": "Search memories using natural language semantic search. Returns the most relevant memories ranked by similarity.",
        "parameters": [
          {
            "name": "query",
            "type": "string",
            "description": "Natural language search query",
            "required": true
          },
          {
            "name": "namespace",
            "type": "string",
            "description": "Filter results to a specific namespace",
            "required": false
          },
          {
            "name": "tags",
            "type": "array",
            "description": "Filter results to memories with any of these tags",
            "required": false
          },
          {
            "name": "limit",
            "type": "number",
            "description": "Maximum number of results (default: 10, max: 50)",
            "required": false
          },
          {
            "name": "threshold",
            "type": "number",
            "description": "Minimum similarity threshold 0-1 (default: 0.7)",
            "required": false
          }
        ],
        "returns": {
          "type": "SearchResult[]",
          "description": "Array of matching memories with similarity scores"
        }
      }
    ]
  },
  "dependencies": {
    "ai": "6.0.49"
  }
}

