    45→export default function MemoriesPage(): React.ReactElement {
    46→  const [memories, setMemories] = useState<Memory[]>([]);
    47→  const [isLoading, setIsLoading] = useState(true);
    48→  const [error, setError] = useState<string | null>(null);
    49→  const [deletingId, setDeletingId] = useState<string | null>(null);
    50→  const [selectedMemory, setSelectedMemory] = useState<Memory | null>(null);
    51→  const [searchQuery, setSearchQuery] = useState('');
    52→  const [isSearching, setIsSearching] = useState(false);
    53→  const [namespaceFilter, setNamespaceFilter] = useState<string>('');
    54→  const [namespaces, setNamespaces] = useState<string[]>([]);
    55→
    56→  const fetchMemories = useCallback(async () => {
    57→    try {
    58→      setIsLoading(true);
    59→      const params = new URLSearchParams();
    60→      if (namespaceFilter) params.set('namespace', namespaceFilter);
    61→
    62→      const response = await fetch(`/api/memories?${params.toString()}`);
    63→      const data = await response.json();
    64→
    65→      if (data.success) {
    66→        setMemories(data.data);
    67→        // Extract unique namespaces for the filter
    68→        const ns = new Set<string>();
    69→        for (const m of data.data) {
    70→          if (m.namespace) ns.add(m.namespace);
    71→        }
    72→        setNamespaces(Array.from(ns).sort());
    73→      } else {
    74→        setError(data.error || 'Failed to fetch memories');
    75→      }
    76→    } catch (err) {
    77→      console.error('Failed to fetch memories:', err);
    78→      setError('Failed to fetch memories');
    79→    } finally {
    80→      setIsLoading(false);
    81→    }
    82→  }, [namespaceFilter]);
    83→
    84→  useEffect(() => {
    85→    fetchMemories();
    86→  }, [fetchMemories]);
    87→
    88→  const handleSearch = async () => {
    89→    if (!searchQuery.trim()) {
    90→      fetchMemories();
    91→      return;
