    94→    setIsSearching(true);
    95→    try {
    96→      const response = await fetch('/api/memories/search', {
    97→        method: 'POST',
    98→        headers: { 'Content-Type': 'application/json' },
    99→        body: JSON.stringify({
   100→          query: searchQuery,
   101→          namespace: namespaceFilter || undefined,
   102→          limit: 50,
   103→        }),
   104→      });
   105→      const data = await response.json();
   106→      if (data.success) {
   107→        setMemories(data.data);
   108→      } else {
   109→        setError(data.error || 'Search failed');
   110→      }
   111→    } catch (err) {
