   131→        alert(result.error || 'Failed to delete memory');
   132→      }
   133→    } catch (err) {
   134→      console.error('Failed to delete memory:', err);
   135→      alert('Failed to delete memory');
   136→    } finally {
   137→      setDeletingId(null);
   138→    }
   139→  };
   140→
   141→  if (error) {
   142→    return (
   143→      <DashboardLayout title="Memories">
   144→        <div className="text-center py-16">
