   175→            value={searchQuery}
   176→            onChange={(e) => setSearchQuery(e.target.value)}
   177→            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
   178→          />
   179→        </div>
   180→        {namespaces.length > 0 && (
   181→          <select
   182→            value={namespaceFilter}
   183→            onChange={(e) => setNamespaceFilter(e.target.value)}
   184→            className="px-3 py-2 rounded-lg border border-border bg-surface text-foreground text-sm"
   185→          >
   186→            <option value="">All namespaces</option>
   187→            {namespaces.map((ns) => (
