   653→// biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Agent detail page has multiple interconnected features
   654→export default function AgentDetailPage(): React.ReactElement {
   655→  const params = useParams();
   656→  const router = useRouter();
   657→  const searchParams = useSearchParams();
   658→  const agentId = params.id as string;
   659→
   660→  // Get initial tab from URL or default to 'tools'
   661→  const tabFromUrl = searchParams.get('tab') as PageTabId | null;
   662→  const initialTab = tabFromUrl && VALID_TABS.includes(tabFromUrl) ? tabFromUrl : 'tools';
   663→
   664→  const [agent, setAgent] = useState<Agent | null>(null);
   665→  const [isLoading, setIsLoading] = useState(true);
   666→  const [isSaving, setIsSaving] = useState(false);
   667→  const [error, setError] = useState<string | null>(null);
   668→  const [executorConfig, setExecutorConfig] = useState<ExecutorConfig | null>(null);
   669→  const [activeTab, setActiveTab] = useState<PageTabId>(initialTab);
   670→
   671→  // Update URL when tab changes
   672→  const handleTabChange = (tabId: string) => {
   673→    const newTab = tabId as PageTabId;
   674→    setActiveTab(newTab);
   675→    const newParams = new URLSearchParams(searchParams.toString());
   676→    if (newTab === 'tools') {
   677→      newParams.delete('tab');
   678→    } else {
   679→      newParams.set('tab', newTab);
   680→    }
   681→    const queryString = newParams.toString();
   682→    router.replace(`/dashboard/agents/${agentId}${queryString ? `?${queryString}` : ''}`, {
   683→      scroll: false,
   684→    });
   685→  };
   686→
   687→  // Tools state
   688→  const [agentTools, setAgentTools] = useState<AgentTool[]>([]);
   689→  const [toolSearch, setToolSearch] = useState('');
   690→  const [toolSearchResults, setToolSearchResults] = useState<SearchTool[]>([]);
   691→  const [isSearchingTools, setIsSearchingTools] = useState(false);
   692→  const [showToolSearch, setShowToolSearch] = useState(false);
   693→  const toolSearchRef = useRef<HTMLDivElement>(null);
   694→
   695→  // Collections state
   696→  const [agentCollections, setAgentCollections] = useState<AgentCollection[]>([]);
   697→  const [collectionSearch, setCollectionSearch] = useState('');
   698→  const [collectionSearchResults, setCollectionSearchResults] = useState<SearchCollection[]>([]);
   699→  const [isSearchingCollections, setIsSearchingCollections] = useState(false);
   700→  const [showCollectionSearch, setShowCollectionSearch] = useState(false);
   701→  const collectionSearchRef = useRef<HTMLDivElement>(null);
   702→
   703→  const [formData, setFormData] = useState({
   704→    name: '',
   705→    uid: '',
   706→    description: '',
   707→    provider: 'OPENAI' as AIProvider,
   708→    modelId: '',
   709→    systemPrompt: '',
   710→    temperature: 0.7,
   711→    maxToolCallsPerTurn: 20,
   712→    maxMessagesInContext: 10,
   713→    isPublic: true,
   714→  });
   715→
   716→  // Environment variables state (stored as object for the EnvVarsEditor component)
   717→  const [envVars, setEnvVars] = useState<Record<string, string> | null>(null);
   718→
   719→  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Multiple state initialization from fetched data
   720→  const fetchAgent = useCallback(async () => {
   721→    try {
   722→      const response = await fetch(`/api/agents/${agentId}`);
   723→      const data = await response.json();
   724→
   725→      if (data.success) {
   726→        setAgent(data.data);
   727→        setFormData({
   728→          name: data.data.name,
   729→          uid: data.data.uid,
   730→          description: data.data.description || '',
   731→          provider: data.data.provider,
   732→          modelId: data.data.modelId,
   733→          systemPrompt: data.data.systemPrompt || '',
   734→          temperature: data.data.temperature,
   735→          maxToolCallsPerTurn: data.data.maxToolCallsPerTurn,
   736→          maxMessagesInContext: data.data.maxMessagesInContext,
   737→          isPublic: data.data.isPublic,
   738→        });
   739→        // Initialize executor config state from agent data
   740→        if (data.data.executorType === 'custom_url' && data.data.executorConfig) {
   741→          setExecutorConfig({
   742→            type: 'custom_url',
   743→            url: data.data.executorConfig.url,
   744→            apiKey: data.data.executorConfig.apiKey,
   745→          });
   746→        } else {
   747→          setExecutorConfig(data.data.executorType ? { type: 'default' } : null);
   748→        }
   749→        // Initialize env vars from agent data
   750→        if (data.data.envVars && typeof data.data.envVars === 'object') {
   751→          setEnvVars(data.data.envVars as Record<string, string>);
   752→        } else {
   753→          setEnvVars(null);
   754→        }
   755→      } else {
   756→        if (response.status === 401) {
   757→          router.push('/sign-in');
   758→          return;
   759→        }
   760→        setError(data.error || 'Failed to fetch agent');
   761→      }
   762→    } catch (err) {
   763→      console.error('Failed to fetch agent:', err);
   764→      setError('Failed to fetch agent');
   765→    } finally {
   766→      setIsLoading(false);
   767→    }
   768→  }, [agentId, router]);
   769→
   770→  // Fetch tools attached to agent
   771→  const fetchAgentTools = useCallback(async () => {
   772→    try {
   773→      const response = await fetch(`/api/agents/${agentId}/tools`);
   774→      const data = await response.json();
   775→      if (data.success) {
   776→        setAgentTools(data.data || []);
   777→      }
   778→    } catch (err) {
   779→      console.error('Failed to fetch agent tools:', err);
   780→    }
   781→  }, [agentId]);
   782→
   783→  // Fetch collections attached to agent
   784→  const fetchAgentCollections = useCallback(async () => {
   785→    try {
   786→      const response = await fetch(`/api/agents/${agentId}/collections`);
   787→      const data = await response.json();
   788→      if (data.success) {
   789→        setAgentCollections(data.data || []);
   790→      }
   791→    } catch (err) {
   792→      console.error('Failed to fetch agent collections:', err);
   793→    }
   794→  }, [agentId]);
   795→
   796→  useEffect(() => {
   797→    fetchAgent();
   798→  }, [fetchAgent]);
   799→
   800→  useEffect(() => {
   801→    if (agent) {
   802→      fetchAgentTools();
   803→      fetchAgentCollections();
   804→    }
   805→  }, [agent, fetchAgentTools, fetchAgentCollections]);
   806→
   807→  // Click outside handler for search dropdowns
   808→  useEffect(() => {
   809→    function handleClickOutside(event: MouseEvent) {
   810→      if (toolSearchRef.current && !toolSearchRef.current.contains(event.target as Node)) {
   811→        setShowToolSearch(false);
   812→      }
   813→      if (
   814→        collectionSearchRef.current &&
   815→        !collectionSearchRef.current.contains(event.target as Node)
   816→      ) {
   817→        setShowCollectionSearch(false);
   818→      }
   819→    }
   820→    document.addEventListener('mousedown', handleClickOutside);
   821→    return () => document.removeEventListener('mousedown', handleClickOutside);
   822→  }, []);
   823→
   824→  // Search tools
   825→  const searchTools = useCallback(
   826→    async (query: string) => {
   827→      if (!query.trim()) {
   828→        setToolSearchResults([]);
   829→        return;
   830→      }
   831→      setIsSearchingTools(true);
   832→      try {
   833→        const response = await fetch(`/api/tools/search?q=${encodeURIComponent(query)}&limit=10`);
   834→        const data = await response.json();
   835→        if (data.success && data.results?.tools) {
   836→          // Filter out tools already attached and map to expected shape
   837→          const attachedToolIds = new Set(agentTools.map((t) => t.toolId));
   838→          const filtered = data.results.tools
   839→            .filter((t: { id: string }) => !attachedToolIds.has(t.id))
   840→            .map(
   841→              (t: {
   842→                id: string;
   843→                name: string;
   844→                description: string | null;
   845→                package: { npmPackageName: string };
   846→              }) => ({
   847→                id: t.id,
   848→                name: t.name,
   849→                description: t.description,
   850→                npmPackageName: t.package.npmPackageName,
   851→              })
   852→            );
   853→          setToolSearchResults(filtered);
   854→        }
   855→      } catch (err) {
   856→        console.error('Failed to search tools:', err);
   857→      } finally {
   858→        setIsSearchingTools(false);
   859→      }
   860→    },
   861→    [agentTools]
   862→  );
   863→
   864→  // Search collections
   865→  const searchCollections = useCallback(
   866→    async (query: string) => {
   867→      if (!query.trim()) {
   868→        setCollectionSearchResults([]);
   869→        return;
   870→      }
   871→      setIsSearchingCollections(true);
   872→      try {
   873→        const response = await fetch(
   874→          `/api/collections?search=${encodeURIComponent(query)}&limit=10`
   875→        );
   876→        const data = await response.json();
   877→        if (data.success) {
   878→          // Filter out collections already attached
   879→          const attachedCollectionIds = new Set(agentCollections.map((c) => c.collectionId));
   880→          const filtered = (data.data || []).filter(
   881→            (c: SearchCollection) => !attachedCollectionIds.has(c.id)
   882→          );
   883→          setCollectionSearchResults(filtered);
   884→        }
   885→      } catch (err) {
   886→        console.error('Failed to search collections:', err);
   887→      } finally {
   888→        setIsSearchingCollections(false);
   889→      }
   890→    },
   891→    [agentCollections]
   892→  );
   893→
   894→  // Debounced search effects
   895→  useEffect(() => {
   896→    const timer = setTimeout(() => {
   897→      if (toolSearch) searchTools(toolSearch);
   898→    }, 300);
   899→    return () => clearTimeout(timer);
   900→  }, [toolSearch, searchTools]);
   901→
   902→  useEffect(() => {
   903→    const timer = setTimeout(() => {
   904→      if (collectionSearch) searchCollections(collectionSearch);
   905→    }, 300);
   906→    return () => clearTimeout(timer);
   907→  }, [collectionSearch, searchCollections]);
   908→
   909→  // Add tool to agent
   910→  const addTool = async (toolId: string) => {
