     8→import { API_KEY_SCOPES } from '~/lib/api-keys';
     9→import { requireAuth } from '~/lib/api-keys/middleware';
    10→
    11→export const runtime = 'nodejs';
    12→export const maxDuration = 60;
    13→
    14→const MAX_CONTENT_SIZE = 100 * 1024; // 100KB
    15→
    16→/**
    17→ * POST /api/memories - Create a new memory
    18→ */
    19→export async function POST(request: Request) {
    20→  const { auth, errorResponse } = await requireAuth(API_KEY_SCOPES.MEMORY_WRITE);
    21→  if (errorResponse) return errorResponse;
    22→
    23→  let body: Record<string, unknown>;
    24→  try {
    25→    body = await request.json();
    26→  } catch {
    27→    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 });
    28→  }
    29→
    30→  const { content, summary, namespace, tags, expiresAt, source, sourceAgent, sourceContext } = body as {
    31→    content: unknown;
    32→    summary?: string;
    33→    namespace?: string;
    34→    tags?: string[];
    35→    expiresAt?: string;
    36→    source?: string;
    37→    sourceAgent?: string;
    38→    sourceContext?: unknown;
    39→  };
    40→
    41→  if (content === undefined || content === null) {
    42→    return NextResponse.json({ error: 'content is required' }, { status: 400 });
    43→  }
    44→
    45→  const contentStr = JSON.stringify(content);
    46→  const contentSizeBytes = Buffer.byteLength(contentStr, 'utf-8');
    47→
    48→  if (contentSizeBytes > MAX_CONTENT_SIZE) {
    49→    return NextResponse.json(
    50→      { error: `content exceeds maximum size of ${MAX_CONTENT_SIZE} bytes` },
    51→      { status: 400 }
    52→    );
    53→  }
    54→
    55→  // Auto-generate summary if not provided
    56→  const memorySummary = summary || contentStr.slice(0, 500);
    57→
