    60→    memorySummary,
    61→    namespace,
    62→    tags
    63→  );
    64→  const embedding = await embedMemoryContent(embeddingText);
    65→
    66→  const memory = await prisma.memory.create({
    67→    data: {
    68→      userId: auth!.userId!,
    69→      content: content as Prisma.InputJsonValue,
    70→      summary: memorySummary,
    71→      namespace: namespace || null,
    72→      tags: tags || [],
    73→      embedding: embedding as unknown as Prisma.InputJsonValue,
    74→      source: (source as string) || 'api',
