    77→      contentSizeBytes,
    78→      expiresAt: expiresAt ? new Date(expiresAt) : null,
    79→    },
    80→    select: {
    81→      id: true,
    82→      content: true,
    83→      summary: true,
    84→      namespace: true,
    85→      tags: true,
    86→      source: true,
    87→      sourceAgent: true,
    88→      sourceContext: true,
    89→      contentSizeBytes: true,
    90→      expiresAt: true,
    91→      createdAt: true,
    92→      updatedAt: true,
    93→    },
    94→  });
    95→
    96→  return NextResponse.json({ success: true, data: memory }, { status: 201 });
    97→}
    98→
    99→/**
   100→ * GET /api/memories - List memories
   101→ */
   102→export async function GET(request: Request) {
   103→  const { auth, errorResponse } = await requireAuth(API_KEY_SCOPES.MEMORY_READ);
   104→  if (errorResponse) return errorResponse;
   105→
   106→  const url = new URL(request.url);
   107→  const limit = Math.min(Number(url.searchParams.get('limit')) || 50, 100);
   108→  const offset = Number(url.searchParams.get('offset')) || 0;
   109→  const namespace = url.searchParams.get('namespace');
   110→  const tagsParam = url.searchParams.get('tags');
   111→
   112→  const where: Record<string, unknown> = {
   113→    userId: auth!.userId!,
   114→    OR: [{ expiresAt: null }, { expiresAt: { gt: new Date() } }],
   115→  };
