   444→                      toolName: tr.toolName,
   445→                      toolCallId: tr.toolCallId,
   446→                      error: tr.output,
   447→                    });
   448→                  } else {
   449→                    console.log('[Agent] Tool execution success:', {
   450→                      toolName: tr.toolName,
   451→                      toolCallId: tr.toolCallId,
   452→                      outputPreview: JSON.stringify(tr.output).slice(0, 200),
   453→                    });
   454→                  }
   455→
   456→                  sendEvent('tool_result', {
