   464→                    toolCallId: tr.toolCallId,
   465→                    toolName: tr.toolName,
   466→                    output: tr.output,
   467→                  });
   468→
   469→                  // Track each tool call execution event
   470→                  trackExecution({
   471→                    eventType: 'tool_call',
   472→                    source: 'agent_chat',
   473→                    userId: authResult.userId ?? undefined,
   474→                    apiKeyId: authResult.apiKeyId ?? undefined,
   475→                    agentId: agent.id,
   476→                    toolName: tr.toolName,
   477→                    status: isError ? 'error' : 'success',
   478→                  });
   479→                }
   480→              }
   481→
   482→              // Track token usage
   483→              if (usage) {
   484→                inputTokens += usage.inputTokens ?? 0;
   485→                outputTokens += usage.outputTokens ?? 0;
   486→              }
   487→            },
   488→          });
   489→
   490→          // Stream text chunks
   491→          for await (const chunk of result.textStream) {
   492→            fullContent += chunk;
   493→            sendEvent('chunk', { type: 'text', text: chunk });
   494→          }
   495→
   496→          // Get final response data
   497→          const finalUsage = await result.usage;
   498→
   499→          // Convert tool calls map to array for storage
   500→          const allToolCalls = Array.from(toolCallsMap.values());
   501→
   502→          // Update token counts from final usage
   503→          if (finalUsage) {
   504→            inputTokens = finalUsage.inputTokens ?? inputTokens;
   505→            outputTokens = finalUsage.outputTokens ?? outputTokens;
   506→          }
   507→
   508→          // Save assistant message FIRST (so it has earlier createdAt than tool results)
   509→          const assistantMessage = await prisma.message.create({
   510→            data: {
   511→              conversationId: conversation.id,
   512→              role: 'ASSISTANT',
   513→              content: fullContent,
   514→              // Cast to Prisma-compatible JSON type
   515→              toolCalls:
   516→                allToolCalls.length > 0
   517→                  ? (allToolCalls as unknown as Prisma.InputJsonValue)
   518→                  : Prisma.JsonNull,
   519→              inputTokens,
   520→              outputTokens,
   521→            },
   522→          });
   523→
   524→          // Now save TOOL messages (after assistant, for correct chronological order)
   525→          for (const tr of pendingToolResults) {
   526→            await prisma.message.create({
   527→              data: {
   528→                conversationId: conversation.id,
   529→                role: 'TOOL',
   530→                content: JSON.stringify(tr.output),
   531→                toolCallId: tr.toolCallId,
   532→                toolName: tr.toolName,
   533→                toolResult: tr.output as object,
   534→              },
   535→            });
   536→          }
   537→
   538→          // Update conversation timestamp
   539→          await prisma.conversation.update({
   540→            where: { id: conversation.id },
   541→            data: { updatedAt: new Date() },
   542→          });
   543→
   544→          const executionTimeMs = Date.now() - startTime;
   545→
   546→          // Send token usage
   547→          sendEvent('tokens', {
   548→            inputTokens,
   549→            outputTokens,
   550→            totalTokens: inputTokens + outputTokens,
   551→          });
   552→
   553→          // Send completion event
   554→          sendEvent('complete', {
   555→            messageId: assistantMessage.id,
   556→            conversationId: conversation.id,
   557→            executionTimeMs,
   558→          });
   559→
   560→          // Track agent run execution event
   561→          trackExecution({
   562→            eventType: 'agent_run',
   563→            source: 'agent_chat',
   564→            userId: authResult.userId ?? undefined,
   565→            apiKeyId: authResult.apiKeyId ?? undefined,
   566→            agentId: agent.id,
   567→            status: 'success',
   568→            durationMs: executionTimeMs,
   569→            tokensIn: inputTokens,
   570→            tokensOut: outputTokens,
   571→          });
   572→
   573→          // Track usage
   574→          if (authResult.userId) {
   575→            trackUsage({
   576→              apiKeyId: authResult.apiKeyId ?? undefined,
   577→              userId: authResult.userId,
   578→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
   579→              method: 'POST',
   580→              statusCode: 200,
   581→              latencyMs: executionTimeMs,
   582→              resourceType: 'agent',
   583→              resourceId: agentId,
   584→              tokensIn: inputTokens,
   585→              tokensOut: outputTokens,
   586→              model: agent.modelId,
   587→            });
   588→          }
   589→        } catch (error) {
   590→          // Log detailed error for debugging
   591→          console.error('[Agent] Conversation stream error:', {
   592→            error: error instanceof Error ? error.message : String(error),
   593→            stack: error instanceof Error ? error.stack : undefined,
   594→            agentId: agent.id,
   595→            conversationId: conversation.id,
   596→          });
   597→          sendEvent('error', {
   598→            message: error instanceof Error ? error.message : 'Unknown error',
   599→          });
   600→
   601→          // Track agent run error
   602→          trackExecution({
   603→            eventType: 'agent_run',
   604→            source: 'agent_chat',
   605→            userId: authResult.userId ?? undefined,
   606→            apiKeyId: authResult.apiKeyId ?? undefined,
   607→            agentId: agent.id,
   608→            status: 'error',
   609→            durationMs: Date.now() - startTime,
   610→            errorMessage: error instanceof Error ? error.message : 'Unknown error',
   611→          });
   612→
   613→          // Track error
   614→          if (authResult.userId) {
   615→            trackUsage({
   616→              apiKeyId: authResult.apiKeyId ?? undefined,
   617→              userId: authResult.userId,
   618→              endpoint: `/api/agents/${agentId}/conversation/${conversationId}`,
   619→              method: 'POST',
   620→              statusCode: 500,
   621→              latencyMs: Date.now() - startTime,
   622→              resourceType: 'agent',
   623→              resourceId: agentId,
   624→              errorCode: 'STREAM_ERROR',
   625→              errorMessage: error instanceof Error ? error.message : 'Unknown error',
   626→            });
   627→          }
   628→        } finally {
   629→          controller.close();
   630→        }
   631→      },
   632→    });
   633→
   634→    return new NextResponse(stream, {
   635→      headers: {
   636→        'Content-Type': 'text/event-stream',
   637→        'Cache-Control': 'no-cache',
   638→        Connection: 'keep-alive',
   639→      },
   640→    });
   641→  } catch (error) {
   642→    console.error('Failed to process message:', error);
   643→    return NextResponse.json(
   644→      {
   645→        success: false,
   646→        error: error instanceof Error ? error.message : 'Failed to process message',
   647→      },
   648→      { status: 500 }
