   653→/**
   654→ * GET /api/agents/[id]/conversation/[conversationId]
   655→ * Retrieve conversation history with pagination
   656→ *
   657→ * Query params:
   658→ * - limit: Max messages to return (default: 50, max: 100)
   659→ * - before: Fetch messages created before this ISO timestamp (for loading older messages)
   660→ * - after: Fetch messages created after this ISO timestamp (for loading newer messages)
   661→ * - format: 'json' for full debug view (no pagination, includes agent info)
   662→ *
   663→ * Default behavior (no before/after): Returns the most recent messages
   664→ * With before: Returns messages older than the timestamp (for scrolling up)
   665→ * With after: Returns messages newer than the timestamp (for refreshing)
   666→ */
   667→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
   668→  const { id: agentId, conversationId } = await context.params;
   669→  const { searchParams } = new URL(request.url);
   670→
   671→  const format = searchParams.get('format');
   672→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '50', 10), 100);
   673→  const before = searchParams.get('before');
   674→  const after = searchParams.get('after');
   675→
   676→  try {
   677→    // Fetch agent by ID with more details for JSON format
   678→    const agent = await prisma.agent.findUnique({
   679→      where: { id: agentId },
   680→      select: {
   681→        id: true,
   682→        uid: true,
   683→        name: true,
   684→        provider: true,
   685→        modelId: true,
   686→        executorType: true,
   687→        executorConfig: true,
   688→      },
   689→    });
   690→
   691→    if (!agent) {
   692→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
   693→    }
   694→
   695→    // Fetch conversation
   696→    const conversation = await prisma.conversation.findUnique({
   697→      where: {
   698→        agentId_slug: {
   699→          agentId: agent.id,
   700→          slug: conversationId,
   701→        },
   702→      },
   703→    });
   704→
   705→    if (!conversation) {
   706→      return NextResponse.json(
   707→        { success: false, error: 'Conversation not found' },
   708→        { status: 404 }
   709→      );
   710→    }
   711→
   712→    // For JSON format, return all messages with full details
   713→    if (format === 'json') {
   714→      const allMessages = await prisma.message.findMany({
   715→        where: { conversationId: conversation.id },
   716→        orderBy: { createdAt: 'asc' },
   717→      });
   718→
   719→      const response = {
   720→        _meta: {
   721→          exportedAt: new Date().toISOString(),
   722→          format: 'tpmjs-conversation-log',
   723→          version: '1.0',
   724→        },
   725→        agent: {
   726→          id: agent.id,
   727→          uid: agent.uid,
   728→          name: agent.name,
   729→          provider: agent.provider,
   730→          modelId: agent.modelId,
   731→          executorType: agent.executorType,
   732→          executorConfig: agent.executorConfig,
   733→        },
   734→        conversation: {
   735→          id: conversation.id,
   736→          slug: conversation.slug,
   737→          title: conversation.title,
   738→          createdAt: conversation.createdAt,
   739→          updatedAt: conversation.updatedAt,
   740→          messageCount: allMessages.length,
   741→        },
   742→        messages: allMessages.map((m) => ({
   743→          id: m.id,
   744→          role: m.role,
   745→          content: m.content,
   746→          toolCalls: m.toolCalls,
   747→          toolCallId: m.toolCallId,
   748→          toolName: m.toolName,
   749→          toolResult: m.toolResult,
   750→          inputTokens: m.inputTokens,
   751→          outputTokens: m.outputTokens,
   752→          createdAt: m.createdAt,
   753→        })),
   754→        stats: {
   755→          totalMessages: allMessages.length,
   756→          userMessages: allMessages.filter((m) => m.role === 'USER').length,
   757→          assistantMessages: allMessages.filter((m) => m.role === 'ASSISTANT').length,
   758→          toolResults: allMessages.filter((m) => m.role === 'TOOL').length,
   759→          totalInputTokens: allMessages.reduce((sum, m) => sum + (m.inputTokens || 0), 0),
   760→          totalOutputTokens: allMessages.reduce((sum, m) => sum + (m.outputTokens || 0), 0),
   761→        },
   762→      };
   763→
   764→      // Return pretty-printed JSON with proper content type
   765→      return new NextResponse(JSON.stringify(response, null, 2), {
   766→        headers: {
   767→          'Content-Type': 'application/json',
   768→          'Content-Disposition': `inline; filename="${conversation.slug}-logs.json"`,
   769→        },
   770→      });
   771→    }
   772→
   773→    // Standard paginated response
   774→    const whereClause: {
   775→      conversationId: string;
   776→      createdAt?: { lt?: Date; gt?: Date };
   777→    } = { conversationId: conversation.id };
   778→
   779→    if (before) {
   780→      whereClause.createdAt = { lt: new Date(before) };
   781→    } else if (after) {
   782→      whereClause.createdAt = { gt: new Date(after) };
   783→    }
   784→
   785→    // Determine fetch order:
   786→    // - Default (no cursor) or "before": Fetch desc (newest first), then reverse for chronological order
   787→    // - "after": Fetch asc (oldest first) to get messages after the cursor
   788→    const shouldFetchDesc = !after;
   789→
   790→    // Fetch messages
   791→    const messages = await prisma.message.findMany({
   792→      where: whereClause,
   793→      orderBy: { createdAt: shouldFetchDesc ? 'desc' : 'asc' },
   794→      take: limit + 1,
   795→    });
   796→
   797→    const hasMore = messages.length > limit;
   798→    let paginatedMessages = hasMore ? messages.slice(0, limit) : messages;
   799→
   800→    // Reverse if we fetched in desc order to maintain chronological order
   801→    if (shouldFetchDesc) {
   802→      paginatedMessages = paginatedMessages.reverse();
   803→    }
   804→
   805→    const mappedMessages = paginatedMessages.map((m) => ({
   806→      id: m.id,
   807→      role: m.role,
   808→      content: m.content,
   809→      toolCalls: m.toolCalls,
   810→      toolCallId: m.toolCallId,
   811→      toolName: m.toolName,
   812→      toolResult: m.toolResult,
   813→      inputTokens: m.inputTokens,
   814→      outputTokens: m.outputTokens,
   815→      createdAt: m.createdAt,
   816→    }));
   817→
   818→    return NextResponse.json({
   819→      success: true,
   820→      data: {
   821→        id: conversation.id,
   822→        slug: conversation.slug,
   823→        title: conversation.title,
   824→        createdAt: conversation.createdAt,
   825→        updatedAt: conversation.updatedAt,
   826→        messages: mappedMessages,
   827→      },
   828→      pagination: {
   829→        limit,
   830→        hasMore,
   831→        ...(before && { before }),
   832→        ...(after && { after }),
   833→      },
   834→    });
   835→  } catch (error) {
   836→    console.error('Failed to fetch conversation:', error);
   837→    return NextResponse.json(
   838→      { success: false, error: 'Failed to fetch conversation' },
   839→      { status: 500 }
   840→    );
   841→  }
   842→}
