   844→/**
   845→ * DELETE /api/agents/[id]/conversation/[conversationId]
   846→ * Delete a conversation
   847→ */
   848→export async function DELETE(_request: NextRequest, context: RouteContext): Promise<NextResponse> {
   849→  const { id: agentId, conversationId } = await context.params;
   850→
   851→  try {
   852→    // Fetch agent by ID
   853→    const agent = await prisma.agent.findUnique({
