    18→/**
    19→ * GET /api/agents/[id]/conversations
    20→ * List all conversations for an agent (accepts id or uid)
    21→ */
    22→export async function GET(request: NextRequest, context: RouteContext): Promise<NextResponse> {
    23→  const { id: idOrUid } = await context.params;
    24→  const { searchParams } = new URL(request.url);
    25→
    26→  const limit = Math.min(Number.parseInt(searchParams.get('limit') || '20', 10), 100);
    27→  const offset = Number.parseInt(searchParams.get('offset') || '0', 10);
    28→
    29→  try {
    30→    // Fetch agent by id or uid
    31→    const agent = await prisma.agent.findFirst({
    32→      where: {
    33→        OR: [{ id: idOrUid }, { uid: idOrUid }],
    34→      },
    35→      select: { id: true },
    36→    });
    37→
    38→    if (!agent) {
    39→      return NextResponse.json({ success: false, error: 'Agent not found' }, { status: 404 });
