    41→
    42→    // Fetch conversations with message count
    43→    const conversations = await prisma.conversation.findMany({
    44→      where: { agentId: agent.id },
    45→      orderBy: { updatedAt: 'desc' },
    46→      take: limit + 1,
    47→      skip: offset,
    48→      include: {
    49→        _count: {
    50→          select: { messages: true },
    51→        },
    52→      },
    53→    });
    54→
    55→    const hasMore = conversations.length > limit;
    56→    const data = hasMore ? conversations.slice(0, limit) : conversations;
