    60→      data: data.map((c) => ({
    61→        id: c.id,
    62→        slug: c.slug,
    63→        title: c.title,
    64→        messageCount: c._count.messages,
    65→        createdAt: c.createdAt,
    66→        updatedAt: c.updatedAt,
    67→      })),
    68→      pagination: {
    69→        limit,
    70→        offset,
    71→        hasMore,
    72→      },
    73→    });
    74→  } catch (error) {
    75→    console.error('Failed to fetch conversations:', error);
    76→    return NextResponse.json(
    77→      { success: false, error: 'Failed to fetch conversations' },
    78→      { status: 500 }
    79→    );
    80→  }
    81→}
