   175→          tool: {
   176→            include: { package: true },
   177→          },
   178→        },
   179→        orderBy: { position: 'asc' },
   180→      },
   181→    },
   182→  });
   183→}
   184→
   185→/**
   186→ * Sanitize npm package name to valid tool name
   187→ * OpenAI limits tool names to 64 characters
   188→ */
   189→function sanitizeToolName(name: string): string {
   190→  const sanitized = name.replace(/[@/]/g, '-').replace(/^-+/, '');
   191→  // Truncate to 64 chars (OpenAI limit)
   192→  return sanitized.slice(0, 64);
   193→}
   194→
   195→/**
   196→ * Parse environment variables from JSON field
   197→ * Returns empty object if null/undefined or invalid
   198→ */
   199→function parseEnvVars(envVars: unknown): Record<string, string> {
   200→  if (!envVars || typeof envVars !== 'object') {
   201→    return {};
   202→  }
   203→  // Validate all values are strings
   204→  const result: Record<string, string> = {};
   205→  for (const [key, value] of Object.entries(envVars)) {
   206→    if (typeof value === 'string') {
   207→      result[key] = value;
   208→    }
   209→  }
   210→  return result;
   211→}
   212→
   213→/**
   214→ * Merge environment variables with agent envVars taking precedence
   215→ * Collection envVars are used as base, agent envVars override
   216→ */
   217→function mergeEnvVars(
   218→  collectionEnvVars: Record<string, string>,
   219→  agentEnvVars: Record<string, string>
   220→): Record<string, string> {
   221→  return {
   222→    ...collectionEnvVars,
   223→    ...agentEnvVars, // Agent overrides collection
   224→  };
   225→}
   226→
   227→/**
   228→ * Build all tools from an agent's collections and individual tools
   229→ * Returns a map of tool name -> AI SDK tool definition
   230→ *
   231→ * Executor config cascade: Agent → Collection → System Default
   232→ * - If agent has an executor config, it's used for all tools
   233→ * - If agent has no config but collection has one, collection's config is used for tools from that collection
   234→ * - If neither has config, system default is used
   235→ *
   236→ * Environment variables cascade: Agent → Collection (merged, agent overrides)
   237→ * - Collection env vars are used as base
   238→ * - Agent env vars override collection env vars for same keys
   239→ * - Both are merged together for unique keys
   240→ *
   241→ * @param agent - The agent with tool relations
   242→ * @param callerEnvVars - Optional env vars provided by the caller (for non-owners accessing public agents).
   243→ *                        When provided, these are used INSTEAD of the agent's stored env vars.
   244→ */
   245→export function buildAgentTools(
   246→  agent: AgentWithRelations,
   247→  callerEnvVars?: Record<string, string>
   248→): Record<string, ReturnType<typeof createToolDefinition>> {
   249→  const tools: Record<string, ReturnType<typeof createToolDefinition>> = {};
   250→  const seenTools = new Set<string>();
   251→
   252→  // Parse agent-level executor config
   253→  const agentExecutorConfig = parseExecutorConfig(agent.executorType, agent.executorConfig);
   254→
   255→  // When callerEnvVars is provided (non-owner using public agent), use those exclusively.
   256→  // Otherwise, use the agent's stored env vars.
   257→  const useCallerEnvVars = callerEnvVars !== undefined;
   258→  const agentEnvVars = useCallerEnvVars ? callerEnvVars : parseEnvVars(agent.envVars);
   259→
   260→  // Add tools from collections first
   261→  for (const agentCollection of agent.collections) {
   262→    const collection = agentCollection.collection;
   263→
   264→    // Parse collection-level executor config
   265→    const collectionExecutorConfig = parseExecutorConfig(
   266→      collection.executorType,
   267→      collection.executorConfig
   268→    );
   269→
   270→    // Resolve executor config: Agent → Collection → Default
   271→    const resolvedConfig = resolveExecutorConfig(agentExecutorConfig, collectionExecutorConfig);
   272→
   273→    // Parse collection-level env vars and merge with agent env vars
   274→    // When callerEnvVars is provided, skip collection env vars entirely
   275→    const collectionEnvVars = useCallerEnvVars ? {} : parseEnvVars(collection.envVars);
   276→    const mergedEnvVars = mergeEnvVars(collectionEnvVars, agentEnvVars);
   277→
   278→    for (const collectionTool of collection.tools) {
   279→      const tool = collectionTool.tool;
   280→      const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
   281→
   282→      // Avoid duplicates
   283→      if (seenTools.has(toolKey)) continue;
   284→      seenTools.add(toolKey);
   285→
   286→      const toolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
   287→      tools[toolName] = createToolDefinition(tool, resolvedConfig, mergedEnvVars);
   288→    }
   289→  }
   290→
   291→  // Add individual tools (may override collection tools)
   292→  // Individual tools use agent config or system default (no collection context)
   293→  // Individual tools only use agent env vars (no collection context)
   294→  const individualToolConfig = agentExecutorConfig ?? { type: 'default' as const };
   295→
   296→  for (const agentTool of agent.tools) {
   297→    const tool = agentTool.tool;
   298→    const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
   299→
   300→    // Skip if already added from collections
   301→    if (seenTools.has(toolKey)) continue;
   302→    seenTools.add(toolKey);
   303→
   304→    const toolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
   305→    tools[toolName] = createToolDefinition(tool, individualToolConfig, agentEnvVars);
   306→  }
   307→
   308→  return tools;
   309→}
   310→
   311→/**
   312→ * Get list of tool names for an agent (for display)
   313→ */
   314→export function getAgentToolNames(agent: AgentWithRelations): string[] {
   315→  const names: string[] = [];
   316→  const seenTools = new Set<string>();
   317→
   318→  for (const agentCollection of agent.collections) {
   319→    for (const collectionTool of agentCollection.collection.tools) {
   320→      const tool = collectionTool.tool;
   321→      const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
   322→      if (!seenTools.has(toolKey)) {
   323→        seenTools.add(toolKey);
   324→        names.push(sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`));
   325→      }
   326→    }
   327→  }
   328→
   329→  for (const agentTool of agent.tools) {
   330→    const tool = agentTool.tool;
   331→    const toolKey = `${tool.package.npmPackageName}::${tool.name}`;
   332→    if (!seenTools.has(toolKey)) {
   333→      seenTools.add(toolKey);
   334→      names.push(sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`));
   335→    }
   336→  }
   337→
   338→  return names;
   339→}
