   133→
   134→/**
   135→ * Check which required env vars are missing from provided env vars
   136→ * Returns only the required vars that don't have defaults and aren't provided
   137→ */
   138→export function getMissingEnvVars(
   139→  requiredEnvVars: TpmjsEnv[],
   140→  providedEnvVars: Record<string, string>
   141→): TpmjsEnv[] {
   142→  return requiredEnvVars.filter(
   143→    (env) => env.required !== false && !env.default && !providedEnvVars[env.name]
   144→  );
   145→}
   146→
   147→/**
   148→ * Validate that provided env var names are in the allowed list
   149→ * Returns invalid names that shouldn't be accepted
   150→ */
   151→export function getInvalidEnvVarNames(
   152→  providedEnvVars: Record<string, string>,
   153→  allowedEnvNames: string[]
   154→): string[] {
   155→  return Object.keys(providedEnvVars).filter((name) => !allowedEnvNames.includes(name));
   156→}
