     1→/**
     2→ * AI Agent service for executing TPMJS tools
     3→ * Converts TPMJS metadata to Zod schemas and executes with AI SDK v6
     4→ */
     5→
     6→import { openai } from '@ai-sdk/openai';
     7→import type { Package, Tool } from '@tpmjs/db';
     8→import type { ExecutorConfig } from '@tpmjs/types/executor';
     9→import { generateText, jsonSchema, type ModelMessage } from 'ai';
    10→import { z } from 'zod';
    11→
    12→import { executeWithExecutor } from '../executors';
    13→
    14→/**
    15→ * Parameter from TPMJS metadata
    16→ */
    17→interface TPMJSParameter {
    18→  name: string;
    19→  type: string;
    20→  required: boolean;
    21→  description: string;
    22→  default?: unknown;
    23→}
    24→
    25→/**
    26→ * Token usage breakdown
    27→ */
    28→export interface TokenBreakdown {
    29→  inputTokens: number;
    30→  toolDescTokens: number;
    31→  schemaTokens: number;
    32→  outputTokens: number;
    33→  totalTokens: number;
    34→  estimatedCost: number;
    35→}
    36→
    37→/**
    38→ * Convert TPMJS parameter type to Zod schema
    39→ */
    40→function typeToZodSchema(type: string): z.ZodTypeAny {
    41→  // Handle array types
    42→  if (type.endsWith('[]')) {
    43→    const baseType = type.slice(0, -2);
    44→    return z.array(typeToZodSchema(baseType));
    45→  }
    46→
    47→  // Handle union types (e.g., 'markdown' | 'mdx')
    48→  if (type.includes('|')) {
    49→    const types = type.split('|').map((t) => t.trim().replace(/'/g, ''));
    50→    return z.enum(types as [string, ...string[]]);
    51→  }
    52→
    53→  // Handle primitive types
    54→  switch (type) {
    55→    case 'string':
    56→      return z.string();
    57→    case 'number':
    58→      return z.number();
    59→    case 'boolean':
    60→      return z.boolean();
    61→    case 'object':
    62→      return z.object({});
    63→    default:
    64→      // Default to string for unknown types
    65→      return z.string();
    66→  }
    67→}
    68→
    69→/**
    70→ * Convert TPMJS parameters to Zod schema object
    71→ */
    72→// biome-ignore lint/suspicious/noExplicitAny: Zod requires any for dynamic schema objects
    73→export function tpmjsParamsToZodSchema(parameters: TPMJSParameter[]): z.ZodObject<any> {
    74→  const shape: Record<string, z.ZodTypeAny> = {};
    75→
    76→  for (const param of parameters) {
    77→    let schema = typeToZodSchema(param.type);
    78→
    79→    // Add description
    80→    schema = schema.describe(param.description);
    81→
    82→    // Make optional if not required
    83→    if (!param.required) {
    84→      schema = schema.optional();
    85→    }
    86→
    87→    shape[param.name] = schema;
    88→  }
    89→
    90→  return z.object(shape);
    91→}
    92→
    93→/**
    94→ * Create AI SDK v6 tool definition from TPMJS Tool
    95→ * Requires Tool with Package relation
    96→ *
    97→ * @param tool - The tool with its package relation
    98→ * @param executorConfig - Optional executor config for custom executors
    99→ * @param envVars - Optional environment variables to pass to the tool
   100→ */
   101→export function createToolDefinition(
   102→  tool: Tool & { package: Package },
   103→  executorConfig?: ExecutorConfig | null,
   104→  envVars?: Record<string, string>
   105→) {
   106→  console.log('[createToolDefinition] Tool:', tool.package.npmPackageName, '/', tool.name);
   107→
   108→  // Prefer full inputSchema if available (has nested object/array structures)
   109→  // Fall back to legacy parameters array conversion if not
   110→  const inputSchema =
   111→    tool.inputSchema && typeof tool.inputSchema === 'object'
   112→      ? // Use full JSON Schema directly - preserves nested array/object structures
   113→        jsonSchema(tool.inputSchema as Parameters<typeof jsonSchema>[0])
   114→      : // Legacy: convert flattened parameters array to Zod schema
   115→        (() => {
   116→          const parameters = Array.isArray(tool.parameters)
   117→            ? (tool.parameters as unknown as TPMJSParameter[])
   118→            : [];
   119→          console.log('[createToolDefinition] Using legacy parameters:', parameters.length);
   120→          return parameters.length > 0
   121→            ? tpmjsParamsToZodSchema(parameters)
   122→            : z.object({}).describe('No parameters required');
   123→        })();
   124→
   125→  const sanitizedName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
   126→
   127→  // AI SDK v6 tool definition
   128→  return {
   129→    description: tool.description,
   130→    inputSchema, // AI SDK v6 uses inputSchema
   131→    execute: async (params: Record<string, unknown>) => {
   132→      console.log('[Tool execute] Running:', sanitizedName, params);
   133→      if (envVars && Object.keys(envVars).length > 0) {
   134→        console.log('[Tool execute] With env vars:', Object.keys(envVars));
   135→      }
   136→
   137→      // Execute the actual npm package using resolved executor
   138→      // Use the actual export name from the Tool record
   139→      // Pass explicit version to avoid Deno HTTP import cache issues with @latest
   140→      const result = await executeWithExecutor(executorConfig ?? null, {
   141→        packageName: tool.package.npmPackageName,
   142→        name: tool.name, // Use actual export name (e.g., "helloWorldTool", "default")
   143→        version: tool.package.npmVersion,
   144→        params,
   145→        env: envVars && Object.keys(envVars).length > 0 ? envVars : undefined,
   146→      });
   147→
   148→      if (!result.success) {
   149→        // Log detailed error for debugging
   150→        console.error('[Tool execute] FAILED:', sanitizedName, {
   151→          error: result.error,
   152→          executionTimeMs: result.executionTimeMs,
   153→          params: JSON.stringify(params).slice(0, 200),
   154→        });
   155→        throw new Error(result.error || 'Package execution failed');
   156→      }
   157→
   158→      console.log('[Tool execute] Success:', sanitizedName, {
   159→        executionTimeMs: result.executionTimeMs,
   160→        outputPreview: JSON.stringify(result.output).slice(0, 200),
   161→      });
   162→      return result.output;
   163→    },
   164→  };
   165→}
   166→
   167→/**
   168→ * Count tokens in text using character estimation
   169→ * Uses rough estimation: ~4 characters per token
   170→ * This is used instead of tiktoken to avoid WASM dependency issues in serverless
   171→ */
   172→function countTokens(text: string): number {
   173→  return Math.ceil(text.length / 4);
   174→}
   175→
   176→/**
   177→ * Calculate token breakdown for tool execution
   178→ */
   179→export function calculateTokenBreakdown(
   180→  userPrompt: string,
   181→  toolDescription: string,
   182→  parameters: TPMJSParameter[],
   183→  returns: unknown,
   184→  output: string
   185→): TokenBreakdown {
   186→  const inputTokens = countTokens(userPrompt);
   187→  const toolDescTokens = countTokens(toolDescription);
   188→  const schemaTokens = countTokens(JSON.stringify({ parameters, returns }));
   189→  const outputTokens = countTokens(output);
   190→  const totalTokens = inputTokens + toolDescTokens + schemaTokens + outputTokens;
   191→
   192→  // GPT-4 Turbo pricing (approximate)
   193→  const inputCost = (inputTokens + toolDescTokens + schemaTokens) * (0.01 / 1000);
   194→  const outputCost = outputTokens * (0.03 / 1000);
   195→  const estimatedCost = inputCost + outputCost;
   196→
   197→  return {
   198→    inputTokens,
   199→    toolDescTokens,
   200→    schemaTokens,
   201→    outputTokens,
   202→    totalTokens,
   203→    estimatedCost,
   204→  };
   205→}
   206→
   207→/**
   208→ * Sanitize npm package name to valid OpenAI tool name
   209→ * OpenAI tool names must match: ^[a-zA-Z0-9_-]+
   210→ * Converts: @tpmjs/createblogpost -> tpmjs-createblogpost
   211→ */
   212→function sanitizeToolName(npmPackageName: string): string {
   213→  return npmPackageName.replace(/[@/]/g, '-').replace(/^-+/, '');
   214→}
   215→
   216→/**
   217→ * Execute tool with AI agent using AI SDK v6
   218→ * Requires Tool with Package relation
   219→ */
   220→export async function executeToolWithAgent(
   221→  tool: Tool & { package: Package },
   222→  userPrompt: string,
   223→  onChunk?: (chunk: string) => void,
   224→  onTokenUpdate?: (tokens: Partial<TokenBreakdown>) => void
   225→) {
   226→  const toolDef = createToolDefinition(tool);
   227→  const sanitizedToolName = sanitizeToolName(`${tool.package.npmPackageName}-${tool.name}`);
   228→
   229→  console.log('[executeToolWithAgent] Tool name:', sanitizedToolName);
   230→
   231→  const messages: ModelMessage[] = [
   232→    {
   233→      role: 'user',
   234→      content: userPrompt,
   235→    },
   236→  ];
   237→
   238→  const toolsConfig = {
   239→    [sanitizedToolName]: toolDef,
   240→  };
   241→
   242→  console.log('[executeToolWithAgent] Calling generateText');
   243→
   244→  // Use generateText for tool execution
   245→  const result = await generateText({
   246→    model: openai('gpt-4-turbo'),
   247→    messages,
   248→    tools: toolsConfig,
   249→  });
   250→
   251→  console.log('[executeToolWithAgent] Result:', JSON.stringify(result, null, 2));
   252→
   253→  // Extract tool results from the response
   254→  let toolOutput: unknown = null;
   255→  if (result.response?.messages) {
   256→    for (const message of result.response.messages) {
   257→      if (message.role === 'tool' && 'content' in message) {
   258→        toolOutput = message.content;
   259→        console.log('[executeToolWithAgent] Tool output found:', toolOutput);
   260→        break;
   261→      }
   262→    }
   263→  }
   264→
   265→  // Format the output as JSON
   266→  const fullOutput = toolOutput
   267→    ? JSON.stringify(toolOutput, null, 2)
   268→    : result.text || JSON.stringify(result, null, 2);
   269→
   270→  console.log('[executeToolWithAgent] Final output:', fullOutput);
   271→
   272→  // Stream the output (all at once since generateText is non-streaming)
   273→  if (onChunk) {
   274→    onChunk(fullOutput);
   275→  }
   276→
   277→  // Calculate final token breakdown
   278→  const parameters = Array.isArray(tool.parameters)
   279→    ? (tool.parameters as unknown as TPMJSParameter[])
   280→    : [];
   281→  const tokenBreakdown = calculateTokenBreakdown(
   282→    userPrompt,
   283→    tool.description,
   284→    parameters,
   285→    tool.returns,
   286→    fullOutput
   287→  );
   288→
   289→  onTokenUpdate?.(tokenBreakdown);
   290→
   291→  return {
   292→    output: fullOutput,
   293→    tokenBreakdown,
   294→    agentSteps: result.steps?.length || 1,
   295→  };
   296→}
