    20→/**
    21→ * Execute a package function with parameters via remote sandbox
    22→ */
    23→export async function executePackage(
    24→  packageName: string,
    25→  functionName: string,
    26→  params: Record<string, unknown>,
    27→  options: ExecutorOptions = {}
    28→): Promise<ExecutionResult> {
    29→  const startTime = Date.now();
    30→  const timeout = options.timeout || DEFAULT_TIMEOUT;
    31→
    32→  try {
    33→    // Call the remote sandbox service
    34→    const controller = new AbortController();
    35→    const timeoutId = setTimeout(() => controller.abort(), timeout);
    36→
    37→    // Build request body, only include env if provided
    38→    // Use explicit version if provided to avoid Deno HTTP import cache issues
    39→    const requestBody: Record<string, unknown> = {
    40→      packageName,
    41→      name: functionName,
    42→      version: options.version || 'latest',
    43→      params,
    44→    };
    45→    if (options.env && Object.keys(options.env).length > 0) {
    46→      requestBody.env = options.env;
    47→    }
    48→
    49→    const response = await fetch(`${getSandboxUrl()}/execute-tool`, {
    50→      method: 'POST',
    51→      headers: {
    52→        'Content-Type': 'application/json',
    53→      },
    54→      body: JSON.stringify(requestBody),
    55→      signal: controller.signal,
    56→    });
    57→
    58→    clearTimeout(timeoutId);
    59→
    60→    const executionTimeMs = Date.now() - startTime;
    61→
    62→    if (!response.ok) {
    63→      const errorData = (await response.json().catch(() => ({ error: 'Unknown error' }))) as {
    64→        error?: string;
    65→      };
    66→      return {
    67→        success: false,
    68→        error: errorData.error || `Sandbox service error: ${response.status}`,
    69→        executionTimeMs,
    70→      };
    71→    }
    72→
    73→    const result = (await response.json()) as {
    74→      success: boolean;
    75→      output?: unknown;
    76→      error?: string;
    77→      executionTimeMs?: number;
    78→    };
    79→
    80→    return {
    81→      success: result.success,
    82→      output: result.output,
    83→      error: result.error,
    84→      executionTimeMs: result.executionTimeMs || executionTimeMs,
    85→    };
    86→  } catch (error) {
    87→    const executionTimeMs = Date.now() - startTime;
    88→
    89→    if (error instanceof Error && error.name === 'AbortError') {
    90→      return {
    91→        success: false,
    92→        error: 'Execution timeout',
    93→        executionTimeMs,
    94→      };
    95→    }
    96→
    97→    return {
    98→      success: false,
    99→      error: error instanceof Error ? error.message : String(error),
   100→      executionTimeMs,
   101→    };
   102→  }
   103→}
